import { LazyQueryHookOptions, useLazyQuery } from '@apollo/client';
import { useEffect, useState } from 'react';
import useAxios from './useAxios';
import { GET_TOKENIZED_DOCUMENT_QUERY } from '../api/queries/getTokenizedDocumentUrl';
import { diagnosisGapsLogger } from '../logic/logger';
import { DocumentData, HighlightArea, SupportedFileExtension } from '../types';

type UseGetTokenizedDocumentData = [
  getTokenizedDocument: (options?: LazyQueryHookOptions) => void,
  documentFullData: DocumentData,
  loaded: boolean,
];

export default function useGetTokenizedDocumentData(): UseGetTokenizedDocumentData {
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [fetchFailed, setFetchFailed] = useState<boolean>();

  const [documentUrl, setDocumentUrl] = useState<string>();
  const [documentHighlights, setDocumentHighlights] = useState<HighlightArea[]>();

  const [documentBuffer, setDocumentBuffer] = useState<ArrayBuffer>();
  const [documentHeaders, setDocumentHeaders] = useState();

  const [documentFullData, setDocumentFullData] = useState<DocumentData>({});

  // TODO use regular query
  const [
    getTokenizedDocument,
    { loading: getTokenizedDocumentLoading, error: getTokenizedDocumentError, data: documentData },
  ] = useLazyQuery(GET_TOKENIZED_DOCUMENT_QUERY, {
    fetchPolicy: 'network-only',
  });

  const [axiosLoaded, buffer, headers, axiosError]: [boolean, ArrayBuffer?, any?, any?] = useAxios(
    documentUrl,
    'arraybuffer',
  );

  useEffect(() => {
    if (!getTokenizedDocumentLoading) {
      if (getTokenizedDocumentError) {
        diagnosisGapsLogger.error('Failed to fetch tokenized document url', {
          error: getTokenizedDocumentError,
        });
        setFetchFailed(true);
        setIsLoading(false);
      } else if (!documentData?.getTokenizedDocument) {
        setIsLoading(false);
      } else if (documentData) {
        diagnosisGapsLogger.info('GetTokenizedDocumentUrl fetched successfully', {
          result: documentData,
        });
        const { url, highlights = [] } = documentData?.getTokenizedDocument ?? {};
        setDocumentUrl(url);
        setDocumentHighlights(highlights);
      }
    }
  }, [getTokenizedDocumentError, documentData, getTokenizedDocumentLoading]);

  useEffect(() => {
    if (axiosLoaded) {
      if (axiosError) {
        diagnosisGapsLogger.error('AxiosError while fetching document data', {
          error: axiosError,
        });
        setFetchFailed(true);
      } else if (buffer) {
        setDocumentBuffer(buffer);
        setDocumentHeaders(headers);
      }
      setIsLoading(false);
    }
  }, [axiosLoaded, buffer, axiosError, headers]);

  useEffect(() => {
    if (!axiosLoaded || getTokenizedDocumentLoading) return;
    const documentExtension = documentUrl
      ?.split('?')?.[0]
      .split('.')
      .pop()
      ?.toLowerCase() as SupportedFileExtension;

    setDocumentFullData({
      buffer: documentBuffer,
      highlights: documentHighlights,
      documentExtension,
      requestHeaders: documentHeaders,
      fetchFailed,
    });
  }, [
    documentUrl,
    documentBuffer,
    documentHighlights,
    documentHeaders,
    axiosLoaded,
    getTokenizedDocumentLoading,
    fetchFailed,
  ]);

  return [getTokenizedDocument, documentFullData, isLoading];
}
