import {
  AppPatient,
  ArchivedGapStatusInput,
  AutoResolveGapStatus,
  ContentSupplierSpecificFields,
  DiagnosisGap,
  DiagnosisGapActionStatus,
  DiagnosisGapDiagnosis,
  DiagnosisGapStatus,
  DismissReason,
  EnrichedHcc,
  EvidenceRecord,
  Feature,
  FeedbackActions,
  GapBackground,
  GapSystem,
  GetTokenizedDocumentInput,
  HCC,
  HCC_MODEL_MAPPING,
  ReasonAction,
  Recorder,
} from '../../types';
