import { v4 as uuidv4 } from 'uuid';
import { widgetId } from '../../consts';
import { extractPatientSourceVaultToken } from '@getvim-core-apps/organizations';
import { analyticsManager } from '../../utils/analyticManager';

export type CardState = {
  isUndoClicked: boolean;
  isAutoResolved: boolean;
};

interface DiagnosisGapProps {
  patient?: AppPatient;
  gap: DiagnosisGap;
  onToggle?: any;
  encounter?: Encounter;
  shouldExpandGap?: boolean;
  isManualOpen?: boolean;
  onGapHandle?: (gap: DiagnosisGap, isUndo?: boolean, isAutoResolved?: boolean) => void;
  undoButtonState: UndoButtonState;
  setExpandedGap?: (gap: DiagnosisGap) => void;
  sourceSupportsDocumentViewer?: boolean;
  dismissReasons?: DismissReason[];
  isPerModelEnrichedIcdsLoading?: boolean;
  setAutoResolveStatus?: (status: AutoResolveGapStatus, position?: number) => void;
  getGapAutoResolvedStatus?: (position?: number) => AutoResolveGapStatus | undefined;
}

const setRecordedByString = (recorder_: Recorder | undefined) => {
  if (!recorder_) return;
  const { name, npi } = recorder_;

  if (name && npi) return `${name} ${npi}`;
  if (npi) return npi;
  if (name) return name;
};

const isGapSectionNotEmpty = (sectionChildren) => {
  return (
    Array.isArray(sectionChildren) &&
    sectionChildren.some((child) =>
      Array.isArray(child?.props?.children)
        ? child?.props?.children.some((innerChild) => React.isValidElement(innerChild))
        : React.isValidElement(child?.props?.children),
    )
  );
};

const Diagnosis: FC<{
  contentSupplierSpecificFields: ContentSupplierSpecificFields;
  diagnosis: DiagnosisGapDiagnosis;
}> = ({
  contentSupplierSpecificFields,
  diagnosis: { icd, recordingDate, recorder, notes, source },
}) => {
  const recordedByString: string | undefined = setRecordedByString(recorder);
  const formattedRecordDate = recordingDate ? formatRecordDate(recordingDate) : undefined;

  return (
    <>
      {!!icd && (
        <DetailsCardItem
          label="ICD-10"
          value={
            (
              <>
                <strong>{icd.code ? icd.code.toUpperCase() : icd.code}</strong>&nbsp;-&nbsp;
                {icd.description}
              </>
            ) as React.ReactNode
          }
        />
      )}
      {formattedRecordDate && (
        <DetailsCardItem label="Last recorded on" value={formattedRecordDate} />
      )}

      {recordedByString && (
        <DetailsCardItem
          label="Recorded by"
          value={recordedByString.toLowerCase()}
          valueTextTransform={TextTransformEnum.capitalize}
        />
      )}

      {notes && <DetailsCardItem label="Notes" value={capitalizeLeadingLetter(notes)} />}

      {source && <DetailsCardItem label="Source" value={capitalizeLeadingLetter(source)} />}

      {contentSupplierSpecificFields?.claimedYear && (
        <DetailsCardItem label="Claimed Year" value={contentSupplierSpecificFields.claimedYear} />
      )}
    </>
  );
};

const HCCDetails: FC<{ gap: DiagnosisGap }> = ({
  gap: { hcc, recordedOn, recorder, notes, source },
}) => {
  const hccModelValue = getHccModelValue(hcc);
  return (
    <>
      {hcc?.code && (
        <DetailsCardItem
          label="HCC"
          value={
            <>
              <strong>{hcc.code.toUpperCase()}</strong>
              {hcc.description ? ` - ${hcc.description}` : null}
              {hccModelValue ? ` (${hccModelValue})` : null}
            </>
          }
        />
      )}

      {recordedOn && (
        <DetailsCardItem label="Last recorded on" value={formatRecordDate(recordedOn)} />
      )}
      {!isEmpty(recorder) && renderRecorder(recorder)}
      {notes && <DetailsCardItem label="Notes" value={capitalizeLeadingLetter(notes)} />}
      {source && <DetailsCardItem label="Source" value={capitalizeLeadingLetter(source)} />}
    </>
  );
};

/* eslint-disable @typescript-eslint/no-shadow */
const DiagnosisGapCard: FC<DiagnosisGapProps> = ({
  patient,
  gap,
  onToggle,
  encounter,
  shouldExpandGap,
  isManualOpen,
  onGapHandle,
  undoButtonState: initializedUndoButtonState,
  setExpandedGap,
  sourceSupportsDocumentViewer,
  dismissReasons,
  isPerModelEnrichedIcdsLoading,
  setAutoResolveStatus,
  getGapAutoResolvedStatus,
}) => {
  const {
    platformActions: { isAppOpen, resizeWidget },
  } = useVimOsMigrationAPI();
  const { diagnoses, hcc, gapBackground, contentSupplierSpecificFields } = gap;

  let documentViewerOpenTimer;
  const [cardState, setCardState] = useState<CardState>({
    isUndoClicked: false,
    isAutoResolved: gap.feedbackInProgress && !gap.actionReversed && gap.reason === 'AUTO_RESOLVED',
  });
  const [manualAddToChart, setManualAddToChart] = useState(false);
  const [dismissReason, setDismissReason] = useState<ReasonAction>();
  const [isCardOpened, setIsCardOpened] = useState<boolean>(false);
  const [shouldWriteback, setShouldWriteback] = useState<boolean>(true);
  const [isActionLoading, setActionLoading] = useState<boolean>(false);
  const [isWritebackInProgress, setIsWritebackInProgress] = useState<boolean>(false);

  const [actionClicked, setActionClicked] = useState<FeedbackActions>();

  const {
    shouldAutoResolvedGap,
    shouldSupportUndoMultisession,
    undoActionTime,
    shouldShowHccModel,
    shouldAddAlreadyCodedOnNonSuggestedIcds,
    shouldUseSourceVaultTokens,
  } = useContext(GlobalContext);
  const [undoTimerId, setUndoTimerId] = useState<any | undefined>();
  const [gapStatus, setGapStatus] = useState<DiagnosisGapActionStatus | undefined>(gap.status);
  const [prevEncounterAlreadyCodedIcds, setPrevEncounterAlreadyCodedIcds] = useState<string[]>([]);

  const [diagnosisGapsFeedback] = useFeedback();

  const [undoButtonState, setUndoButtonState] = useState<UndoButtonState>(
    initializedUndoButtonState,
  );

  const shouldShowUndoButtonForGap = useMemo(
    () => undoButtonState !== UndoButtonState.NOT_SUPPORTED,
    [undoButtonState],
  );

  const [showDocumentViewerComponentOnCard, setShowDocumentViewerComponentOnCard] =
    useState<boolean>(false);

  const [updateArchivedGapStatus] = useMutation(UPDATE_ARCHIVED_GAP_STATUS_MUTATION);
  const [getTokenizedDocument, documentFullData] = useGetTokenizedDocumentData();

  const title = getDiagnosisGapTitleByGapSystem(gap);

  const sortedDiagnoses = sortBy(diagnoses, ['priority'], ['desc']);

  const clearTimeoutUndoTimer = () => {
    if (undoTimerId) {
      clearTimeout(undoTimerId);
      setUndoTimerId(undefined);
    }
  };

  const handleTimeoutUndoDisabled = useCallback(() => {
    if (
      ![UndoButtonState.SUPPORTED_DISABLED_TIMEOUT, UndoButtonState.SUPPORTED_DISABLED].includes(
        undoButtonState,
      )
    ) {
      let time = undoActionTime;
      if (gap.feedbackTime && !gap.actionReversed) {
        const diff = dayjs().diff(gap.feedbackTime, 'ms');
        time = undoActionTime - diff;
      }

      if (time > 0) {
        const currentUndoTimerId = setTimeout(() => {
          setUndoButtonState(UndoButtonState.SUPPORTED_DISABLED_TIMEOUT);
        }, time);
        setUndoTimerId(currentUndoTimerId);
      } else {
        setUndoButtonState(UndoButtonState.SUPPORTED_DISABLED_TIMEOUT);
      }
    }
  }, [undoButtonState, undoActionTime, gap.actionReversed, gap.feedbackTime]);

  useEffect(() => {
    if (
      shouldShowUndoButtonForGap &&
      shouldSupportUndoMultisession &&
      gap.feedbackInProgress &&
      !gap.actionReversed &&
      (gap.feedbackAction || cardState.isAutoResolved) &&
      !cardState.isUndoClicked
    ) {
      handleTimeoutUndoDisabled();
    }
  }, [
    shouldShowUndoButtonForGap,
    shouldSupportUndoMultisession,
    gap.feedbackInProgress,
    gap.actionReversed,
    gap.feedbackAction,
    cardState.isUndoClicked,
    cardState.isAutoResolved,
    handleTimeoutUndoDisabled,
  ]);

  const encounterAlreadyCodedIcds = useMemo(
    () => encounter?.assessments?.map((assessment) => assessment.code) || [],
    [encounter?.assessments],
  );

  const getRelevantManuallyAddedIcds = useCallback((): string[] => {
    const gapIcds = gap.diagnoses.map((diagnose) => diagnose.id).filter((icd) => icd) as string[];
    if (shouldAddAlreadyCodedOnNonSuggestedIcds) {
      const enrichedGapIcds = gap?.enrichedIcds?.map((diagnose) => diagnose.code) || [];
      return [...gapIcds, ...enrichedGapIcds].filter((icd) =>
        encounterAlreadyCodedIcds.includes(icd),
      );
    }
    return gapIcds.filter((icd) => encounterAlreadyCodedIcds.includes(icd));
  }, [
    gap.diagnoses,
    gap.enrichedIcds,
    encounterAlreadyCodedIcds,
    shouldAddAlreadyCodedOnNonSuggestedIcds,
  ]);

  useEffect(() => {
    if (sourceSupportsDocumentViewer && gap?.isDocumentUrlExists) {
      const getTokenizedDocumentInput: GetTokenizedDocumentInput = {
        dataSource: gap.dataSource,
        documentUrl: gap.contentSupplierSpecificFields?.documentUrl,
        coordinates: gap.contentSupplierSpecificFields?.coordinates,
      };
      getTokenizedDocumentInput.entityId = gap.entityId;

      if (shouldUseSourceVaultTokens) {
        getTokenizedDocumentInput.sourceVaultToken = extractPatientSourceVaultToken(
          patient?.patientSourceVaultTokens,
          gap.dataSource,
        )?.sourceVaultToken;
      } else {
        getTokenizedDocumentInput.patientToken =
          patient?.contentSupplierIdentifiers?.[gap.dataSource]?.memberToken;
      }
      getTokenizedDocument({
        variables: {
          input: getTokenizedDocumentInput,
        },
      });
    }
  }, [
    gap,
    patient,
    sourceSupportsDocumentViewer,
    getTokenizedDocument,
    shouldUseSourceVaultTokens,
  ]);

  useEffect(() => {
    if (documentFullData.fetchFailed) {
      analyticsManager.track('dx_document_fetch_failed', {
        gap_code: gap.hcc.code,
        app_name: widgetId,
      });
    }
  }, [documentFullData?.fetchFailed, gap.gapId, gap.hcc.code]);

  const renderEvidence = () => {
    const evidencesToRender: EvidenceRecord[] = (
      contentSupplierSpecificFields?.evidenceRecords ?? []
    ).filter((evidenceRecord) => {
      const { code, description, codeType } = evidenceRecord ?? {};
      return code && description && codeType;
    });

    if (isEmpty(evidencesToRender)) return null;

    const renderSingleEvidence = (evidenceRecord, isFirstEvidence = false) => {
      const { code, description, codeType, claimDate, recorderName } = evidenceRecord ?? {};

      const detailsFormatted = `\
      ${capitalizeLeadingLetter(description)} (${codeType.toUpperCase()} ${code.toUpperCase()})`;

      let evidenceInfo = '';
      if (claimDate) {
        evidenceInfo += 'Claim date: ';
        evidenceInfo += formatRecordDate(claimDate);
      }
      if (recorderName) {
        evidenceInfo += '\nRecorded by: ';
        evidenceInfo += startCase(toLower(recorderName));
      }

      const { cardLabel, labelWeight, cardValue } = isFirstEvidence
        ? {
            cardLabel: 'Evidence',
            labelWeight: WeightEnum.bold,
            cardValue: `${detailsFormatted}\n${evidenceInfo}`,
          }
        : {
            cardLabel: detailsFormatted,
            labelWeight: WeightEnum.normal,
            cardValue: isEmpty(evidenceInfo) ? undefined : evidenceInfo,
          };

      return (
        <DetailsCardItem
          label={cardLabel}
          labelWeight={labelWeight}
          value={cardValue}
          shouldBreakLines
        />
      );
    };

    const [firstEvidence, ...rest] = evidencesToRender;
    return (
      <>
        {renderSingleEvidence(firstEvidence, true)}
        {!isEmpty(rest) ? rest.map((evidence) => renderSingleEvidence(evidence)) : null}
      </>
    );
  };

  const renderRiskScore = () => {
    const jhuRiskScore = contentSupplierSpecificFields?.jhuRiskScore;
    return jhuRiskScore && <DetailsCardItem label="JHU Risk Score" value={jhuRiskScore} />;
  };

  const renderHccFirstModel = () => {
    if (!shouldShowHccModel) return null;
    const hccModelValue = getHccModelValue(hcc);
    return (
      hccModelValue && (
        <DetailsCardItem
          label="Model"
          value={hccModelValue}
          valueTextTransform={TextTransformEnum.upperCase}
        />
      )
    );
  };

  const onClickUndo = async (action: FeedbackActions) => {
    const archivedGapStatusInput: ArchivedGapStatusInput = {
      gapId: gap.gapId,
      entityId: gap.entityId,
      hccCode: gap.hcc.code,
      sourcePatientId: gap.sourcePatientId,
      actionReversed: true,
      dataSource: gap.dataSource,
      hccDescription: gap.hcc.description,
    };

    setActionLoading(true);
    await updateArchivedGapStatus({
      variables: {
        input: archivedGapStatusInput,
      },
    }).catch((error) =>
      diagnosisGapsLogger.info('An error occurred when updateArchivedGapStatus', { error }),
    );
    setActionLoading(false);
    analyticsManager.track('dx_undo_action_clicked', {
      reversed_action: action,
      gap_position: gap.position,
      auto_resolved: cardState.isAutoResolved,
      gap_system: gap.gapSystem,
      gap_code: gap.gapCode,
      gap_description: gap.gapDescription,
      entity_id: gap.entityId,
      app_source_displayed: gap.dataSource,
      content_supplier_patient_id: gap.sourcePatientId,
      app_name: widgetId,
    });

    setShouldWriteback(true);
    setGapStatus(undefined);
    onGapHandle?.(gap, true);
    setCardState((prevState) => ({ ...prevState, isAutoResolved: false, isUndoClicked: true }));
    setActionClicked(action);
    clearTimeoutUndoTimer();
    setAutoResolveStatus?.(AutoResolveGapStatus.SCANNED, gap.position);
  };

  const onFeedbackError = useCallback(
    (error: ApolloError) => {
      diagnosisGapsLogger.error(
        'Error occurred while automatically trying to update diagnosis gaps status',
        {
          error,
          entityId: gap?.entityId,
          selectedIcd: gap.diagnoses.map((diagnose) => ({
            code: diagnose?.icd?.code,
            description: diagnose?.icd?.description,
          })),
        },
      );
      setCardState((prevState) => ({ ...prevState, isUndoClicked: false, isAutoResolved: false }));
      setAutoResolveStatus?.(AutoResolveGapStatus.SCANNED, gap.position);
    },
    [gap, setAutoResolveStatus, setCardState],
  );

  const onFeedbackCompleted = useCallback(() => {
    const isAutoResolved = !(gap.actionReversed && gap.reason === 'AUTO_RESOLVED');

    const selectedIcds = gap.diagnoses
      .filter((diagnose) => diagnose?.icd)
      .map((diagnose) => ({
        code: diagnose?.icd!.code,
        description: diagnose?.icd!.description,
      }));

    if (hcc !== undefined && selectedIcds !== undefined) {
      sendGapAgreeSubmittedAnalytic(
        {
          gap,
          isSuccess: false,
          selectedIcds,
          isAutoResolved,
          manuallyWrittenIcds: shouldAutoResolvedGap ? getRelevantManuallyAddedIcds() : [],
        },
        isAppOpen,
      );
    }
  }, [gap, hcc, getRelevantManuallyAddedIcds, shouldAutoResolvedGap, isAppOpen]);

  const handleAutoResolvedGap = useCallback(() => {
    analyticsManager.track('vim_chart_item_click', {
      feature: Feature.CODING_GAPS,
      action: 'open',
      diagnosis_gaps_count: 0,
      is_calender_view: false,
      action_method: 'automatic',
      auto_expand: false,
      gap_background: gap.gapBackground,
      hcc_code: gap.hcc.code,
      hcc_description: gap.hcc.description,
      gap_code: gap.gapCode,
      gap_description: gap.gapDescription,
      gap_system: gap.gapSystem,
      entity_id: gap.entityId,
      app_source_displayed: gap.dataSource,
      content_supplier_patient_id: gap.sourcePatientId,
      app_name: widgetId,
    });

    analyticsManager.track('dx_gap_agree_clicked', {
      position: gap.position,
      app_source_displayed: [gap.dataSource],
      card_opened: isCardOpened,
      auto_expand: shouldExpandGap,
      auto_resolved: true,
      hcc_code: gap.hcc.code,
      hcc_description: gap.hcc.description,
      gap_code: gap.gapCode,
      gap_description: gap.gapDescription,
      gap_system: gap.gapSystem,
      entity_id: gap.entityId,
      content_supplier_patient_id: gap.sourcePatientId,
      app_name: widgetId,
    });

    const isAutoResolved = !(gap.actionReversed && gap.reason === 'AUTO_RESOLVED');
    diagnosisGapsLogger.info(
      'PI feature rollout - This gap is auto-resolved, mark gap agreed but without writeback. Just updating db.',
      {
        entityId: gap?.entityId,
        selectedIcd: gap.diagnoses.map((diagnose) => ({
          code: diagnose?.icd?.code,
          description: diagnose?.icd?.description,
        })),
        isAppOpen: !!isAppOpen,
      },
    );

    const selectedIcds = gap.diagnoses
      .filter((diagnose) => diagnose?.icd)
      .map((diagnose) => ({
        code: diagnose?.icd!.code,
        description: diagnose?.icd!.description,
      }));

    diagnosisGapsFeedback({
      patient,
      gap,
      selectedIcds,
      encounter,
      action: DiagnosisGapActionStatus.AGREE,
      actionReason: getReason(isAutoResolved),
      onCompleted: () => onFeedbackCompleted(),
      onError: (error: ApolloError) => onFeedbackError(error),
    });

    setGapStatus(DiagnosisGapActionStatus.ADD);
    onGapHandle?.(gap, false, true);
  }, [
    encounter,
    gap,
    isCardOpened,
    onGapHandle,
    onFeedbackError,
    patient,
    shouldExpandGap,
    diagnosisGapsFeedback,
    onFeedbackCompleted,
    isAppOpen,
  ]);

  const shouldAutoResolve = useCallback(() => {
    const gapIcds = gap.diagnoses.map((diagnose) => diagnose.id) || [];
    const allSuggestedCodesInEncounter =
      !isEmpty(gapIcds) &&
      gapIcds.every((currentCode) => {
        if (currentCode === undefined) {
          diagnosisGapsLogger.error('[auto-resolved] Found empty icd code - should not get here', {
            gapPosition: gap.position,
            gapDescription: gap.gapDescription,
            gapIcds,
          });
          return false;
        }

        return encounterAlreadyCodedIcds.includes(currentCode);
      });

    const alreadyAutoResolved = gap.reason === 'AUTO_RESOLVED';

    if (allSuggestedCodesInEncounter) {
      diagnosisGapsLogger.info(
        '[auto-resolved] all gap ICD codes found in encounter assessments suggested codes',
        {
          gapPosition: gap.position,
          gapDescription: gap.gapDescription,
          isUndoClicked: cardState.isUndoClicked,
          alreadyAutoResolved: cardState.isAutoResolved,
          feedbackInProgress: gap.feedbackInProgress,
          isWritebackInProgress,
          gapStatus,
          gapReason: gap.reason,
          gapIcds,
          encounterAlreadyCodedIcds,
          sourcePatientId: gap.sourcePatientId,
        },
      );
    }

    return (
      !cardState.isUndoClicked &&
      !cardState.isAutoResolved &&
      !gap.feedbackInProgress &&
      !isWritebackInProgress &&
      isEmpty(gapStatus) &&
      !alreadyAutoResolved &&
      allSuggestedCodesInEncounter
    );
  }, [
    gap.feedbackInProgress,
    gap.diagnoses,
    gap.reason,
    gap.position,
    gap.gapDescription,
    gapStatus,
    cardState.isAutoResolved,
    cardState.isUndoClicked,
    encounterAlreadyCodedIcds,
    isWritebackInProgress,
  ]);

  const attemptAutoGapResolve = useCallback(() => {
    const inUnlockedEncounter = !isEmpty(encounter) && !encounter?.isLocked;
    const isAutoResolveEnabledByAppState = true; // Always enabled since feature flag is always true

    const shouldTryToAutoResolve =
      shouldAutoResolvedGap && inUnlockedEncounter && isAutoResolveEnabledByAppState;

    if (!shouldTryToAutoResolve) return;

    if (shouldAutoResolve()) {
      setAutoResolveStatus?.(AutoResolveGapStatus.READY_TO_AUTO_RESOLVED, gap.position);
      setCardState({ isUndoClicked: false, isAutoResolved: true });
    } else if (!cardState.isAutoResolved) {
      setAutoResolveStatus?.(AutoResolveGapStatus.SCANNED, gap.position);
    }
  }, [
    gap,
    encounter,
    shouldAutoResolvedGap,
    shouldAutoResolve,
    setAutoResolveStatus,
    cardState.isAutoResolved,
    getGapAutoResolvedStatus,
  ]);

  useEffect(() => {
    if (isEmpty(encounterAlreadyCodedIcds)) return;

    const encounterHasNewCodes =
      encounterAlreadyCodedIcds.some((code) => !prevEncounterAlreadyCodedIcds.includes(code)) ||
      prevEncounterAlreadyCodedIcds.some((code) => !encounterAlreadyCodedIcds.includes(code));

    if (encounterHasNewCodes) {
      diagnosisGapsLogger.info('encounter assessments changed', {
        new: encounterAlreadyCodedIcds,
        prev: prevEncounterAlreadyCodedIcds,
        sourcePatientId: gap.sourcePatientId,
      });
      setPrevEncounterAlreadyCodedIcds(encounterAlreadyCodedIcds);
      attemptAutoGapResolve();
    }
  }, [
    encounterAlreadyCodedIcds,
    prevEncounterAlreadyCodedIcds,
    attemptAutoGapResolve,
    gap.sourcePatientId,
  ]);

  useEffect(() => {
    const isAutoResolveGapFullyReady =
      getGapAutoResolvedStatus?.(gap.position) === AutoResolveGapStatus.READY_TO_AUTO_RESOLVED &&
      cardState.isAutoResolved;

    if (isAutoResolveGapFullyReady) {
      handleAutoResolvedGap();
      setAutoResolveStatus?.(AutoResolveGapStatus.AUTO_RESOLVED, gap.position);
    }
  }, [
    cardState.isAutoResolved,
    gap.position,
    getGapAutoResolvedStatus,
    handleAutoResolvedGap,
    setAutoResolveStatus,
  ]);

  useEffect(() => {
    if (shouldExpandGap !== undefined) {
      setIsCardOpened(shouldExpandGap);
    }
  }, [shouldExpandGap]);

  const renderTopStatusBar = (gapStatus) => {
    if (gapStatus) {
      return (
        <DiagnosisGapStatusMessage
          status={gapStatus}
          manualAddToChart={manualAddToChart}
          dismissReason={dismissReason}
          onClickUndo={async (feedbackAction) => {
            setCardState((prevState) => ({
              ...prevState,
              isUndoClicked: !prevState.isUndoClicked,
            }));
            await onClickUndo(feedbackAction);
          }}
          cardState={cardState}
          gap={gap}
          undoButtonState={encounter ? undoButtonState : UndoButtonState.OUT_OF_EXAM}
          isActionLoading={isActionLoading}
        />
      );
    }
    if (
      shouldSupportUndoMultisession &&
      gap.feedbackInProgress &&
      !gap.actionReversed &&
      gap.feedbackAction &&
      shouldShowUndoButtonForGap &&
      !cardState.isUndoClicked
    ) {
      return (
        <InProgressGap
          onClickUndo={onClickUndo}
          undoButtonState={encounter ? undoButtonState : UndoButtonState.OUT_OF_EXAM}
          gap={gap}
          dismissReasons={dismissReasons}
        />
      );
    }
    return (
      <ActionBar
        patient={patient}
        gap={gap}
        isLocked={encounter?.isLocked}
        disabled={!encounter}
        onAgree={(isEncounterUpdated) => {
          if (shouldShowUndoButtonForGap) {
            handleTimeoutUndoDisabled();
          }
          setGapStatus(DiagnosisGapActionStatus.ADD);
          onGapHandle?.(gap);
          setManualAddToChart(!isEncounterUpdated);
          setCardState((prevState) => ({ ...prevState, isUndoClicked: false }));
          setIsWritebackInProgress(false);
        }}
        onWriteback={() => setIsWritebackInProgress(true)}
        onDismiss={(reason) => {
          if (shouldShowUndoButtonForGap) {
            handleTimeoutUndoDisabled();
          }
          setGapStatus(DiagnosisGapActionStatus.DISMISS);
          onGapHandle?.(gap);
          setDismissReason(reason);
          setCardState((prevState) => ({ ...prevState, isUndoClicked: false }));
        }}
        isCardOpened={isCardOpened}
        isAutoExpand={shouldExpandGap && !isManualOpen}
        alreadyCodedIcds={shouldAutoResolvedGap ? getRelevantManuallyAddedIcds() : []}
        shouldWriteback={shouldWriteback}
        dismissReasons={dismissReasons}
        isPerModelEnrichedIcdsLoading={!!isPerModelEnrichedIcdsLoading}
      />
    );
  };

  const renderStatusBar = (gapStatus) => {
    return (
      <>
        {renderTopStatusBar(gapStatus)}
        {cardState.isUndoClicked && (
          <StatusMessage className="undo-action margin-top-10" iconClass="icon-hourglass-bottom">
            {actionClicked === FeedbackActions.DISMISS
              ? 'Action undone.'
              : 'Action undone. Please make sure to remove or update the relevant information in the EHR.'}
          </StatusMessage>
        )}
      </>
    );
  };

  const renderGapLabel = (label: GapBackground | undefined) => {
    if (!label) {
      return undefined;
    }
    return (
      <div className="gap-label-wrapper">
        <div className={`gap-label-tag ${determineGapLabelCssClass(label)}`}>
          <div className="gap-label-text">{upperCaseOnlyFirstLetter(label)} condition</div>
        </div>
        <Tooltip placement="top" tooltipContent={getDescription(label)} bgColor="light">
          <div className="gap-label-question">
            <SvgQuestionMarkIcon />
          </div>
        </Tooltip>
      </div>
    );
  };

  const openDocumentViewerComponent = (gap: DiagnosisGap, isCardOpened: boolean) => {
    analyticsManager.track('dx_document_opened', {
      gap_code: gap.hcc.code,
      gap_description: gap.hcc.description,
      gap_status: gapStatus ? STATUS_ANALYTICS_LABELS[gapStatus] : STATUS_ANALYTICS_LABELS.OPEN,
      card_opened: isCardOpened,
      entity_id: gap.entityId,
      app_source_displayed: gap.dataSource,
      app_name: widgetId,
    });
    if (setExpandedGap) {
      setExpandedGap(gap);
    }
    setShowDocumentViewerComponentOnCard(true);
    resizeWidget(ApplicationSize.LARGE);
    documentViewerOpenTimer = Date.now();
  };

  const closeDocumentViewerComponent = (closeReason: DocumentViewerCloseReason) => {
    setShowDocumentViewerComponentOnCard(false);
    resizeWidget(ApplicationSize.CLASSIC);
    analyticsManager.track('dx_document_closed', {
      gap_code: gap.hcc.code,
      gap_description: gap.hcc.description,
      document_opened_for_time_seconds: Math.floor((Date.now() - documentViewerOpenTimer) / 1000),
      close_reason: closeReason,
      entity_id: gap.entityId,
      app_source_displayed: gap.dataSource,
      app_name: widgetId,
    });
    documentViewerOpenTimer = null;
  };

  const renderDocumentViewerButton = () => {
    return sourceSupportsDocumentViewer && openDocumentViewerComponent ? (
      <>
        <DocumentViewerButton
          onClick={() => {
            openDocumentViewerComponent(gap, isCardOpened);
          }}
          shouldDisable={
            !gap.isDocumentUrlExists ||
            (isEmpty(patient?.contentSupplierIdentifiers?.[gap.dataSource]?.memberToken) &&
              isEmpty(
                extractPatientSourceVaultToken(patient?.patientSourceVaultTokens, gap.dataSource)
                  ?.sourceVaultToken,
              )) ||
            !!documentFullData?.fetchFailed
          }
        />
      </>
    ) : undefined;
  };

  const onCardToggle = (isExpanded: boolean) => {
    setIsCardOpened(isExpanded);
    onToggle(isExpanded, gap);
  };

  const ICDGapInfo: ReactElement = (
    <div className="diagnosis-card__gap-info">
      {!every(
        [
          diagnoses[0]?.recordingDate,
          diagnoses[0]?.recorder?.npi,
          diagnoses[0]?.recorder?.name,
          diagnoses[0]?.notes,
          diagnoses[0]?.source,
        ],
        isEmpty,
      ) && (
        <Diagnosis
          diagnosis={{ ...diagnoses[0], icd: undefined }}
          contentSupplierSpecificFields={contentSupplierSpecificFields}
        />
      )}
      {renderRiskScore()}
      {renderEvidence()}
    </div>
  );

  const GapInfo: ReactElement = (
    <div className="diagnosis-card__gap-info">
      {!every(
        [gap.recordedOn, gap.recorder?.npi, gap.recorder?.name, gap.notes, gap.source],
        isEmpty,
      ) && <HCCDetails gap={{ ...gap, hcc: { code: '' } }} />}
      {renderRiskScore()}
      {renderEvidence()}
      {renderHccFirstModel()}
    </div>
  );

  const GapSubHeader = (
    <div className="diagnosis-gap-subheader">
      {renderGapLabel(gapBackground)}
      {renderDocumentViewerButton()}
    </div>
  );
  const showDocumentViewer = useMemo(
    () => showDocumentViewerComponentOnCard && gap,
    [gap, showDocumentViewerComponentOnCard],
  );

  const renderDiagnosisList = () =>
    sortedDiagnoses.length > 0 && (
      <ul className="diagnosis-list">
        {sortedDiagnoses.map((diagnosis: DiagnosisGapDiagnosis) => (
          <li key={uuidv4()}>
            <div className="inline-block">
              <Diagnosis
                diagnosis={diagnosis}
                contentSupplierSpecificFields={contentSupplierSpecificFields}
              />
            </div>
          </li>
        ))}
      </ul>
    );

  const renderHCCDetails = () => {
    return (
      !every(
        [
          gap.recordedOn,
          gap.recorder?.npi,
          gap.recorder?.name,
          gap.notes,
          gap.source,
          gap.hcc.code,
        ],
        isEmpty,
      ) && <HCCDetails gap={gap} />
    );
  };

  const renderGapInfo = () => {
    if (gap.gapSystem === GapSystem.ICD) {
      return isGapInfoNotEmpty(ICDGapInfo.props.children) && ICDGapInfo;
    }
    return isGapInfoNotEmpty(GapInfo.props.children) && GapInfo;
  };

  return (
    <div>
      {showDocumentViewer && (
        <DocumentViewer
          key={gap?.entityId}
          gap={gap}
          documentData={documentFullData}
          closeDocumentViewerComponent={closeDocumentViewerComponent}
        />
      )}
      <DetailsCard
        className="diagnosis-card"
        title={title}
        iconClass={`gap-icon icon-microscope2 ${gapStatus ? STATUS_ICON_CLASSES[gapStatus] : ''} ${
          manualAddToChart && 'manual-add-to-chart'
        }`}
        onToggle={onCardToggle}
        fontSize="small"
        permanentVisibleFooter={renderStatusBar(gapStatus)}
        expandOnDemand={shouldExpandGap}
        stickyFooter
        subHeader={isGapSectionNotEmpty(GapSubHeader.props.children) ? GapSubHeader : undefined}
      >
        {renderGapInfo()}
        {gap.gapSystem === GapSystem.ICD ? renderHCCDetails() : renderDiagnosisList()}
      </DetailsCard>
    </div>
  );
};

export { DiagnosisGapCard as default };

const STATUS_ICON_CLASSES: Record<DiagnosisGapActionStatus, string> = {
  [DiagnosisGapActionStatus.ADD]: 'agreed',
  [DiagnosisGapActionStatus.AGREE]: 'agreed',
  [DiagnosisGapActionStatus.DISMISS]: 'dismissed',
};

const STATUS_ANALYTICS_LABELS: Record<DiagnosisGapStatus, string> = {
  [DiagnosisGapStatus.ADD]: 'accepted',
  [DiagnosisGapStatus.DISMISS]: 'dismissed',
  [DiagnosisGapStatus.OPEN]: 'open',
};

const getDiagnosisGapTitleByGapSystem = (gap: DiagnosisGap): string => {
  if (gap.gapSystem === GapSystem.ICD) {
    const { diagnoses } = gap;
    if (diagnoses && diagnoses.length > 0) {
      const diagnose = diagnoses[0];
      if (diagnose) {
        const { code, description } = diagnose.icd!;

        return `${code.toUpperCase()}: ${description && capitalizeLeadingLetter(description)}`;
      }
    }
  }
  const { description, code } = gap.hcc;
  return `${description && capitalizeLeadingLetter(description)} (HCC ${code?.toUpperCase()})`;
};

const formatRecordDate = (dateString: string | Date): string | undefined => {
  const date = dayjs(dateString);
  if (!date.isValid()) {
    return undefined;
  }

  return formatDateString(dateString);
};

const determineGapLabelCssClass = (label) => {
  if (label === GapBackground.KNOWN) {
    return 'known-condition';
  }
  if (label === GapBackground.SUSPECTED) {
    return 'suspected-condition';
  }
  return '';
};
const getDescription = (gapBackground): string => {
  if (gapBackground === GapBackground.KNOWN) {
    return 'This potential condition is derived from a diagnosis previously recorded for this patient.';
  }
  if (gapBackground === GapBackground.SUSPECTED) {
    return 'This potential condition is inferred from a suspected diagnosis for this patient.';
  }
  return '';
};

const getHccModelValue = (hcc?: HCC | EnrichedHcc) =>
  hcc?.model && isValidHccCode(hcc.code) && HCC_MODEL_MAPPING[hcc.model];

const renderRecorder = (recorder: Recorder) => {
  if (recorder.name && recorder.npi) {
    return (
      <DetailsCardItem
        label="Recorded by"
        valueTextTransform={TextTransformEnum.capitalize}
        value={`${recorder.name.toLowerCase()}, NPI: ${recorder.npi}`}
      />
    );
  }
  if (recorder.name) {
    return (
      <DetailsCardItem
        label="Recorded by"
        valueTextTransform={TextTransformEnum.capitalize}
        value={`${recorder.name.toLowerCase()}`}
      />
    );
  }
  if (recorder.npi) {
    return <DetailsCardItem label="Recorded by" value={`NPI: ${recorder.npi}`} />;
  }
  return null;
};

const isGapInfoNotEmpty = (gapInfoChildren) =>
  Array.isArray(gapInfoChildren) &&
  gapInfoChildren.some((node) => {
    return React.isValidElement(node);
  });
