import React, { FC, useEffect, useState } from 'react';
import { Popover, usePopoverState } from '@getvim/atomic-ui';
import './DiagnosisGapActionPopover.less';
import { ActionButton } from '../ActionButton/ActionButton';

interface DiagnosisGapActionPopoverProps {
  shown: boolean;
  onShow(): void;
  buttonText: string;
  disabled: boolean;
  onClose(): void;
  isLocked?: boolean;
  shouldShowTooltip?: boolean;
}

export const DiagnosisGapActionPopover: FC<DiagnosisGapActionPopoverProps> = ({
  disabled,
  buttonText,
  shown,
  onShow,
  children,
  onClose,
  isLocked,
  shouldShowTooltip,
}) => {
  const popover = usePopoverState({ placement: 'bottom-start' });
  useEffect(() => {
    if (shown) {
      popover.show();
    } else {
      popover.hide();
    }
  }, [shown]);

  useEffect(() => {
    if (!popover.visible) onClose();
  }, [popover.visible]);

  return (
    <div onClick={(event) => event.stopPropagation()}>
      <Popover
        popover={popover}
        className="diagnosis-gap-action-popover"
        modal
        aria-label={buttonText}
        disclosure={
          <>
            {/* This fragment is intentional because the onClick prop clashes when it's directly in disclosure */}
            <ActionButton
              onClick={onShow}
              isLocked={isLocked}
              disabled={disabled}
              showTooltip={shouldShowTooltip}
            >
              {buttonText}
            </ActionButton>
          </>
        }
      >
        <div onClick={(event) => event.stopPropagation()} style={{ width: '100%' }}>
          {children}
        </div>
      </Popover>
    </div>
  );
};
