const getAutoResolveTailText = (gapIcds: (string | undefined)[]) =>
  `auto resolved based on the patient's documented conditions (ICD 10: <b>${gapIcds.join(
    ', ',
  )}</b>).`;

export const autoResolveNotification = {
  getText: (resolvedGapsCount: number, gapIcds: (string | undefined)[]) => {
    return resolvedGapsCount === 1
      ? `One diagnosis gap was ${getAutoResolveTailText(gapIcds)}`
      : `${resolvedGapsCount} diagnosis gaps were ${getAutoResolveTailText(gapIcds)}`;
  },
  reviewInAppActionButton: 'Review in app',
  closeActionButton: 'Close',
};
