import { isVimOS } from '@getvim-core-apps/vim-os-migration-api';
import { TrackPayload } from '@getvim/internal-vim-os-sdk/types';
import { diagnosisGapsLogger } from '../logic/logger';
import { AppAnalyticsBaseProperties, VimChartAnalyticsEvents } from '../logic/analytics';

export interface DiagnosisGapsAnalyticsClient {
  trackAnalytics: (payload: TrackPayload) => void;
}

export class DiagnosisGapsAnalyticsManager {
  private baseProperties: AppAnalyticsBaseProperties = {
    vim_patient_id: undefined,
    ehr_insurance: undefined,
    vim_insurer: undefined,
  };

  private static analyticsClient: DiagnosisGapsAnalyticsClient;
  public static setAnalyticsClient(client: DiagnosisGapsAnalyticsClient) {
    DiagnosisGapsAnalyticsManager.analyticsClient = client;
  }

  public setPatientBaseProperties({
    vimPatientId,
    ehrInsurance,
    insurer,
  }: {
    vimPatientId: string;
    ehrInsurance: string;
    insurer: string;
  }) {
    diagnosisGapsLogger.debug('[AnalyticsManager]: patient base properties update', {
      vimPatientId,
      ehrInsurance,
      insurer,
    });
    const properties = {
      base_properties: {
        vim_patient: {
          vim_patient_id: vimPatientId,
          ehr_insurance: ehrInsurance,
          vim_insurer: insurer,
        },
      },
    };
    this.baseProperties = { ...this.baseProperties, ...properties };
  }

  public track<T extends keyof VimChartAnalyticsEvents>(
    event: T,
    eventProperties: VimChartAnalyticsEvents[T],
  ) {
    DiagnosisGapsAnalyticsManager.analyticsClient.trackAnalytics({
      event,
      properties: {
        ...eventProperties,
        ...this.baseProperties,
        is_vim_os_app: isVimOS(),
      },
    });
  }
}

export const analyticsManager = new DiagnosisGapsAnalyticsManager();
