import { useVimOsMigrationAPI } from '@getvim-core-apps/vim-os-migration-api';
import { useLazyQuery } from '@apollo/client';
import {
  ButtonGroupComponent,
  Loader,
  Popover,
  TagsList,
  usePopoverState,
} from '@getvim/atomic-ui';
import React, { FC, useContext, useEffect, useState } from 'react';
import { GlobalContext } from '../../contexts/globalContext';
import { getReason } from '../../logic/actions';
import {
  AppPatient,
  DiagnosisGap,
  DiagnosisGapActionStatus,
  DiagnosisGapsDiagnosisWithIcd,
  Feature,
  ICD,
  TriggerType,
} from '../../types';
import { ActionButton } from '../ActionButton/ActionButton';
import { ActionTitle } from '../ActionTitle/ActionTitle';
import { AddToChartLoader } from '../AddToChartLoader/AddToChartLoader';
import { DataLoader } from '../DataLoader/DataLoader';
import '../DiagnosisGapActionPopover/DiagnosisGapActionPopover.less';
import { FailureScreen } from '../FailureScreen/FailureScreen';
import { ManualAddToChartMessage } from '../ManualAddToChartMessage/ManualAddToChartMessage';
import './AddToChartPopover.less';
import { GET_ENRICHED_HCCS_QUERY } from '../../api/queries/getEnrichedHccs';
import { diagnosisGapsLogger } from '../../logic/logger';
import useFeedback, { sendGapAgreeSubmittedAnalytic } from '../../hooks/useFeedback';
import { handleCdeRequestTrigger } from '../../logic/gapsCdeTrigger';
import { widgetId } from '../../consts';
import { analyticsManager } from '../../utils/analyticManager';

interface AddToChartPopoverProps {
  patient: AppPatient | undefined;
  gap: DiagnosisGap;
  isLocked?: boolean;
  disabled: boolean;
  isCardOpened: boolean;
  isAutoExpand?: boolean;
  alreadyCodedIcds: string[];
  shouldWriteback: boolean;
  isWritebackSupported: boolean;
  isPerModelEnrichedIcdsLoading: boolean;

  onSuccess(isEncounterUpdated: boolean): void;

  onWriteback(): void;
}

export const onFeedbackError = (
  error: any,
  data: {
    selectedIcds: ICD[];
    gap: DiagnosisGap;
  },
) => {
  const { selectedIcds, gap } = data;
  sendGapAgreeSubmittedAnalytic({ gap, selectedIcds, isSuccess: false });

  diagnosisGapsLogger.error(
    'An error has occurred while trying to update diagnosis gaps status! Write back might be complete but DB does not match!!',
    {
      error,
      entityId: gap?.entityId,
      selectedIcds,
    },
  );
};

export const onFeedbackCompleted = (
  shouldUseSourceVaultTokens: boolean,
  patient,
  encounter,
  config,
  cdeTriggerSupportedSources,
  cdeTriggerCache,
  setCdeTriggerCache,
  {
    selectedIcds,
    gap,
  }: {
    selectedIcds: ICD[];
    gap: DiagnosisGap;
  },
) => {
  if (cdeTriggerSupportedSources[gap.dataSource]?.includes(TriggerType.GAP_ACCEPTED)) {
    handleCdeRequestTrigger({
      patient,
      dataSource: gap.dataSource,
      encounterId: encounter?.encounterId,
      encounterDate: encounter?.encounterDate,
      orgId: config.organization.id,
      triggerType: TriggerType.GAP_ACCEPTED,
      cache: cdeTriggerCache,
      setCache: setCdeTriggerCache,
      shouldUseSourceVaultTokens,
    });
  }
  if (gap.hcc !== undefined && selectedIcds !== undefined) {
    sendGapAgreeSubmittedAnalytic({ gap, selectedIcds, isSuccess: true });
  }
};

/* eslint-disable @typescript-eslint/no-shadow */
export const AddToChartPopover: FC<AddToChartPopoverProps> = ({
  patient,
  gap,
  isLocked,
  disabled,
  onSuccess,
  onWriteback,
  isCardOpened,
  isAutoExpand,
  alreadyCodedIcds,
  shouldWriteback,
  isWritebackSupported,
  isPerModelEnrichedIcdsLoading,
}) => {
  const {
    config,
    ehrState: { encounter },
    ehrEntities: {
      entitiesActions: { updateEncounter },
    },
  } = useVimOsMigrationAPI();

  const { hcc, entityId, position, enrichedIcds } = gap;

  const diagnoses = gap.diagnoses.filter(
    (diagnosis) => diagnosis?.icd,
  ) as DiagnosisGapsDiagnosisWithIcd[];

  const [isAgreeLoading, setIsAgreeLoading] = useState<boolean>(false);
  const [addDiagnosisFailed, setAddDiagnosisFailed] = useState<boolean>(false);
  const [loading, setLoading] = useState<boolean>(false);
  const [enrichedIcdsFromHccs, setEnrichedIcdsFromHccs] = useState<ICD[]>();
  const popover = usePopoverState({ placement: 'bottom-start' });
  const {
    shouldSelectDataIcds,
    cdeTriggerCache,
    setCdeTriggerCache,
    cdeTriggerSupportedSources,
    shouldUseSourceVaultTokens,
  } = useContext(GlobalContext);

  const [diagnosisGapsFeedback] = useFeedback();

  const defaultSelectedIcds = diagnoses.map((diagnosis) => ({
    code: diagnosis?.icd.code,
    description: diagnosis?.icd.description,
  }));
  const [selectedIcds, setSelectedIcds] = useState<ICD[]>(
    shouldSelectDataIcds ? defaultSelectedIcds : [],
  );

  const onClickAgree = (isEncounterUpdated: boolean) => {
    onSuccess(isEncounterUpdated);
  };

  const [getEnrichedHccs, { loading: isOldLoadingGetEnrichedHccs, error: getEnrichedHccsError }] =
    useLazyQuery(GET_ENRICHED_HCCS_QUERY, {
      fetchPolicy: 'network-only',
      onCompleted: (data) => {
        if (
          data?.getEnrichedHccs &&
          Array.isArray(data.getEnrichedHccs) &&
          data.getEnrichedHccs.length === 1
        ) {
          setEnrichedIcdsFromHccs(data.getEnrichedHccs[0].icds || []);
        }
      },
    });
  const [isButtonClicked, setIsButtonClicked] = useState<boolean>(false);

  useEffect(() => {
    if (getEnrichedHccsError) {
      diagnosisGapsLogger.error('Failed to get hccs with enriched icds', {
        error: getEnrichedHccsError,
      });
    }
  }, [enrichedIcdsFromHccs, getEnrichedHccsError]);

  const toggleIcdSelection = async (icd: ICD) => {
    setSelectedIcds((currentSelectedIcds: ICD[]) => {
      const isIcdSelected = currentSelectedIcds.some(
        (currentSelectedIcd) => currentSelectedIcd.code === icd.code,
      );
      return isIcdSelected
        ? currentSelectedIcds.filter((currentSelectedIcd) => currentSelectedIcd.code !== icd.code)
        : [...currentSelectedIcds, icd];
    });
  };

  const removeSelection = async (icdCode: string) => {
    setSelectedIcds((prevDiagnoses) =>
      prevDiagnoses.filter((diagnosis) => diagnosis.code !== icdCode),
    );
  };

  const triggerWriteback = async (): Promise<void> => {
    await updateEncounter({
      addedDiagnoses: selectedIcds || [],
      addedProcedures: [],
    });
  };
  const onConfirm = async () => {
    let isWritebackSucceeded = false;
    try {
      const withWriteback = isWritebackSupported && shouldWriteback;
      if (withWriteback) {
        setLoading(true);
        onWriteback();
        popover.show();
      } else {
        setIsAgreeLoading(true);
      }
      if (withWriteback) {
        try {
          await triggerWriteback();
          diagnosisGapsLogger.info('Writeback completed successfully', {
            entityId,
            selectedIcds,
          });
          isWritebackSucceeded = true;
        } catch (error: any) {
          if (error?.message !== 'Unimplemented WriteBack Error') {
            diagnosisGapsLogger.error(
              'An error has occurred while trying to writeback diagnosis gaps',
              {
                error,
                entityId,
                selectedIcds,
                vimPatientId: patient?.vimPatientId,
              },
            );
          }
        }
      }
      const actionReason = getReason(false, isWritebackSucceeded);
      diagnosisGapsLogger.info('Sending feedback request', {
        entityId,
        selectedIcds,
        actionReason,
      });

      await diagnosisGapsFeedback({
        patient,
        gap,
        selectedIcds,
        encounter,
        action: DiagnosisGapActionStatus.AGREE,
        actionReason,
        onCompleted: () =>
          onFeedbackCompleted(
            shouldUseSourceVaultTokens,
            patient,
            encounter,
            config,
            cdeTriggerSupportedSources,
            cdeTriggerCache,
            setCdeTriggerCache,
            {
              selectedIcds,
              gap,
            },
          ),
        onError: (error) => onFeedbackError(error, { selectedIcds, gap }),
      });
      if (!isWritebackSucceeded && withWriteback) {
        throw new Error('Failed to mark gap as agreed');
      }

      onClickAgree(withWriteback);
    } catch {
      if (isWritebackSupported) return setAddDiagnosisFailed(true);
      onClickAgree(false);
    } finally {
      setLoading(false);
      setIsAgreeLoading(false);
    }
  };

  const onClose = () => {
    if (shouldSelectDataIcds) {
      setSelectedIcds(defaultSelectedIcds);
    } else {
      setSelectedIcds([]);
    }

    popover.hide();

    setIsButtonClicked(false);
  };

  const handleAddGapToChart = () => {
    setIsButtonClicked(true);
    if (!isCardOpened && !isAutoExpand) {
      analyticsManager.track('vim_chart_item_click', {
        feature: Feature.CODING_GAPS,
        action: 'open',
        diagnosis_gaps_count: 0,
        is_calender_view: false,
        action_method: 'automatic',
        auto_expand: isAutoExpand,
        gap_background: gap.gapBackground,
        hcc_code: gap.hcc.code,
        hcc_description: gap.hcc.description,
        gap_code: gap.gapCode,
        gap_description: gap.gapDescription,
        gap_system: gap.gapSystem,
        entity_id: gap.entityId,
        app_source_displayed: gap.dataSource,
        content_supplier_patient_id: gap.sourcePatientId,
        app_name: widgetId,
      });
    }
    analyticsManager.track('dx_gap_agree_clicked', {
      position,
      app_source_displayed: [gap.dataSource],
      card_opened: isCardOpened,
      auto_expand: isAutoExpand,
      auto_resolved: false,
      gap_background: gap.gapBackground,
      hcc_code: gap.hcc.code,
      hcc_description: gap.hcc.description,
      gap_code: gap.gapCode,
      gap_description: gap.gapDescription,
      gap_system: gap.gapSystem,
      entity_id: gap.entityId,
      content_supplier_patient_id: gap.sourcePatientId,
      app_name: widgetId,
    });
    const isExtraIcdsEmpty =
      !isPerModelEnrichedIcdsLoading &&
      (!enrichedIcds || (enrichedIcds && enrichedIcds.length === 0));

    if (!hcc.code || (defaultSelectedIcds.length === 1 && isExtraIcdsEmpty)) {
      onConfirm();
    } else {
      popover.show();
    }
  };

  const onManualAddToChartClose = () => {
    onClose();
    onSuccess(false);
  };

  const renderButtons = () => (
    <div className="add-to-chart-footer">
      <div className="diagnosis-gap-action-bar">
        <ActionButton
          onClick={onConfirm}
          disabled={isAgreeLoading || selectedIcds.length === 0}
          tooltipText="&nbsp; At least one ICD has to be chosen"
          showTooltip={!isAgreeLoading || selectedIcds.length === 0}
        >
          {isAgreeLoading ? <DataLoader /> : 'Confirm'}
        </ActionButton>
        <ActionButton onClick={onClose}>Close</ActionButton>
      </div>
    </div>
  );
  return (
    <div onClick={(event) => event.stopPropagation()}>
      <Popover
        hideOnEsc={false}
        modal
        popover={popover}
        className="diagnosis-gap-action-popover"
        aria-label="Agree Popover"
        disclosure={
          <>
            <ActionButton
              onClick={handleAddGapToChart}
              disabled={disabled || isAgreeLoading || isButtonClicked}
              isLocked={isLocked}
              showTooltip={!isAgreeLoading && !isButtonClicked && disabled}
            >
              {isAgreeLoading ? <DataLoader /> : 'Agree'}
            </ActionButton>
          </>
        }
      >
        <div onClick={(event) => event.stopPropagation()} style={{ width: '100%' }}>
          <div className="add-to-chart-content">
            {diagnoses?.length && diagnoses?.every((diagnosis) => !diagnosis?.icd) ? (
              <FailureScreen
                onClose={onManualAddToChartClose}
                text="Unfortunately we cannot add this diagnosis to the note, please make sure to add it."
              />
            ) : (
              <>
                <ActionTitle closeable={!isAgreeLoading && !loading} onClose={onClose}>
                  Add to chart
                </ActionTitle>
                <AddToChartPopoverContent
                  onFailureClose={onManualAddToChartClose}
                  onIcdSelectionChanged={toggleIcdSelection}
                  removeSelection={removeSelection}
                  diagnoses={diagnoses}
                  extraIcds={enrichedIcds}
                  extraIcdsLoading={isPerModelEnrichedIcdsLoading}
                  selectedIcdsCodes={selectedIcds.map((icd) => icd.code)}
                  loading={loading}
                  addDiagnosisFailed={!!addDiagnosisFailed}
                  manualAddToChart={false}
                  onManualAddToChartClose={onManualAddToChartClose}
                  alreadyCodedIcds={alreadyCodedIcds}
                />
                {!loading && !addDiagnosisFailed && renderButtons()}
              </>
            )}
          </div>
        </div>
      </Popover>
    </div>
  );
};

interface AddToChartPopoverContentProps {
  loading: boolean;
  addDiagnosisFailed: boolean;
  diagnoses: DiagnosisGapsDiagnosisWithIcd[];
  extraIcds?: ICD[];
  extraIcdsLoading: boolean;
  selectedIcdsCodes: string[];
  manualAddToChart: boolean;
  alreadyCodedIcds: string[];

  onFailureClose(): void;

  onIcdSelectionChanged(icd: ICD): void;

  removeSelection(icdCode: string): void;

  onManualAddToChartClose(): void;
}

const AddToChartPopoverContent: FC<AddToChartPopoverContentProps> = ({
  loading,
  addDiagnosisFailed,
  onFailureClose,
  diagnoses,
  extraIcds,
  extraIcdsLoading,
  selectedIcdsCodes,
  onIcdSelectionChanged,
  removeSelection,
  manualAddToChart,
  onManualAddToChartClose,
  alreadyCodedIcds,
}) => {
  if (loading) return <AddToChartLoader />;
  if (extraIcdsLoading) return <Loader />;
  if (manualAddToChart) return <ManualAddToChartMessage onClose={onManualAddToChartClose} />;
  if (addDiagnosisFailed)
    return (
      <FailureScreen
        onClose={onFailureClose}
        text="Unfortunately we cannot add this diagnosis to the note, please make sure to add it."
      />
    );

  let diagnosesItems =
    diagnoses?.map(({ icd }) => ({
      text: `${icd.code}: ${icd.description ?? ''}`,
      value: icd.code,
      description: icd.description,
      comment: alreadyCodedIcds.includes(icd.code) ? 'Already coded' : undefined,
    })) || [];

  if (extraIcds?.length) {
    diagnosesItems = diagnosesItems?.filter(
      (icd) =>
        icd.comment === 'Already coded' ||
        !extraIcds.some((item) => item.code === icd.value && item.billable === false),
    );
  }

  const getExtraIcdComment = (icd: ICD): string | undefined => {
    if (alreadyCodedIcds.includes(icd.code)) return 'Already coded';

    return icd.billable === false ? 'Non billable' : undefined;
  };

  const extraIcdsItems =
    extraIcds
      ?.map((icd) => ({
        text: `${icd.code}: ${icd.description ?? ''}`,
        value: icd.code,
        description: icd.description,
        disabled: icd.billable === false,
        comment: getExtraIcdComment(icd),
      }))
      ?.filter((icd) => !diagnosesItems.some((item) => item.value === icd.value)) || [];

  const allIcdItems = [...diagnosesItems, ...extraIcdsItems];

  return (
    <>
      <div className="selected-icds-tags">
        <TagsList listItems={selectedIcdsCodes} onClose={(icdCode) => removeSelection(icdCode)} />
      </div>
      <ButtonGroupComponent
        pinnedItemsTitle="Suggested ICD Codes"
        topPinnedItems={diagnosesItems}
        items={extraIcdsItems}
        value={selectedIcdsCodes}
        width="block"
        color="extraDarkGray"
        buttonType="dropdownOption"
        direction="column"
        searchPlaceholder="Search for ICD Code"
        searchable
        showCheckbox
        multiLines
        shouldColorSelectedItems={false}
        onChange={(code) => {
          const icdItem = allIcdItems.find((diagnosis) => diagnosis.value === code)!;

          onIcdSelectionChanged({
            code: icdItem.value,
            description: icdItem.description,
          });
        }}
        noResultsMessage={diagnosesItems.length > 0 ? '' : 'No results'}
      />
    </>
  );
};
