export type DeepPartial<T> = {
  [K in keyof T]?: T[K] extends object ? DeepPartial<T[K]> : T[K];
};

export type OptionsFlags<T> = {
  [P in keyof T]?: boolean;
};

export type DeepRequired<T> = {
  [K in keyof T]-?: T[K] extends object ? Required<DeepRequired<T[K]>> : Required<T[K]>;
};

export type Nullable<T> = NonNullable<T> | null;

export type PartialToNullable<T> = {
  [K in keyof T]-?: undefined extends T[K] ? Nullable<T[K]> : T[K];
};

export type Nil = null | undefined;

export type NonEmptyArray<T> = [T, ...T[]];

// Solving a known TS issue with Array lengths. See: https://stackoverflow.com/a/56006703
export function isNonEmptyArray<T>(arr: T[]): arr is NonEmptyArray<T> {
  return arr?.length > 0;
}

export type { SnakeCaseKeys } from './snakeCaseKeys';
export type { DotNotationKeys } from './deepDotNotationKeys';

type OptionalKeys<T> = {
  [K in keyof T]-?: Record<string, any> extends Pick<T, K> ? K : never;
}[keyof T];

/**
 * Utility type to convert optional fields to a required that allows undefined;
 * Useful when you want to ensure you never miss passing new fields added to the original type
 */
export type RequireOptionalsAllowUndefined<T> = {
  [K in Exclude<keyof T, OptionalKeys<T>>]: T[K];
} & { [K in OptionalKeys<T>]-?: Exclude<T[K], undefined> | undefined } extends infer O
  ? { [K in keyof O]: O[K] }
  : never;
