export enum AppEnv {
  LOCAL = 'local',
  DEV = 'dev',
  STAGING = 'staging',
  DEMO = 'demo',
  PROD = 'prod',
}

enum Host {
  DEVIM = 'devim.io',
  GETVIM = 'getvim.com',
}

let appEnv: AppEnv;

export async function getAppEnv(): Promise<AppEnv> {
  if (!appEnv) {
    appEnv = (window as any).$vim_environment?.APP_ENV as AppEnv;
  }

  return appEnv;
}

type ServiceUrlConfig = {
  serviceName: string;
  localPort: number;
};

export async function calculateServiceUrl(serviceConfig: ServiceUrlConfig) {
  const { serviceName, localPort } = serviceConfig;

  const appEnv = await getAppEnv();
  if (!appEnv || appEnv === AppEnv.LOCAL) return `http://localhost:${localPort}`;

  const prefix = `https://${serviceName}.`;
  const env = appEnv === AppEnv.PROD ? '' : `${appEnv}.`;
  const suffix = appEnv === AppEnv.DEV ? Host.DEVIM : Host.GETVIM;
  return `${prefix}${env}${suffix}`;
}
