import { DiagnosisGap, Feature } from '../../types';
import { widgetId } from '../../consts';
import { analyticsManager } from '../../utils/analyticManager';

export const sendVimChartItemClickAnalytic = (
  gapsLength: number,
  gap: DiagnosisGap,
  action: 'open' | 'close',
  autoExpand: boolean,
) => {
  analyticsManager.track('vim_chart_item_click', {
    feature: Feature.CODING_GAPS,
    action,
    diagnosis_gaps_count: gapsLength,
    is_calender_view: false,
    action_method: 'manual',
    auto_expand: autoExpand,
    gap_background: gap.gapBackground,
    hcc_code: gap.hcc.code,
    hcc_description: gap.hcc.description,
    gap_code: gap.gapCode,
    gap_description: gap.gapDescription,
    gap_system: gap.gapSystem,
    entity_id: gap.entityId,
    app_source_displayed: gap.dataSource,
    content_supplier_patient_id: gap.sourcePatientId,
    app_name: widgetId,
  });
};

export const getNextNotTreatedGapIndex = (
  gaps: DiagnosisGap[],
  treatedGaps: number[],
  gapsLength: number,
  gap: DiagnosisGap,
): number => {
  if (gap.position && gaps) {
    let gapToOpenIndex = gap.position;
    for (let index = gapToOpenIndex + 1; index < gapsLength + 1; index += 1) {
      if (!treatedGaps.includes(index)) {
        gapToOpenIndex = index;
        break;
      }
    }
    return gapToOpenIndex;
  }
  return 0;
};
