import { useVimOsMigrationAPI } from '@getvim-core-apps/vim-os-migration-api';
import React, { FC, useContext } from 'react';
import { AppPatient, DiagnosisGap, DismissReason, ReasonAction } from '../../types';
import { AddToChartPopover } from '../add-to-chart-popover/AddToChartPopover';
import { DismissPopover } from '../dismiss-popover/DismissPopover';
import './ActionBar.less';
import { GlobalContext } from '../../contexts/globalContext';

interface ActionBarProps {
  patient: AppPatient | undefined;
  gap: DiagnosisGap;
  isLocked?: boolean;
  disabled: boolean;
  onAgree(isEncounterUpdated: boolean): void;
  onWriteback(): void;
  onDismiss(reason: ReasonAction): void;
  isCardOpened: boolean;
  isAutoExpand?: boolean;
  alreadyCodedIcds: string[];
  shouldWriteback: boolean;
  dismissReasons?: DismissReason[];
  isPerModelEnrichedIcdsLoading: boolean;
}

export const ActionBar: FC<ActionBarProps> = ({
  patient,
  gap,
  isLocked,
  disabled,
  onAgree,
  onWriteback,
  onDismiss,
  isCardOpened,
  isAutoExpand,
  alreadyCodedIcds,
  shouldWriteback,
  dismissReasons,
  isPerModelEnrichedIcdsLoading,
}) => {
  const {
    ehrEntities: {
      updatableEntities: {
        encounter: { diagnoses: isDiagnosesUpdatable },
      },
    },
  } = useVimOsMigrationAPI();

  const { shouldAgreeWithoutWriteback } = useContext(GlobalContext);

  return (
    <div className="diagnosis-gap-action-bar">
      <AddToChartPopover
        patient={patient}
        gap={gap}
        isLocked={isLocked}
        disabled={disabled}
        onSuccess={onAgree}
        onWriteback={onWriteback}
        isCardOpened={isCardOpened}
        isAutoExpand={isAutoExpand}
        alreadyCodedIcds={alreadyCodedIcds}
        shouldWriteback={shouldWriteback}
        isWritebackSupported={isDiagnosesUpdatable && !shouldAgreeWithoutWriteback}
        isPerModelEnrichedIcdsLoading={isPerModelEnrichedIcdsLoading}
      />
      <DismissPopover
        patient={patient}
        gap={gap}
        disabled={disabled}
        isLocked={isLocked}
        onDismissSuccess={onDismiss}
        isCardOpened={isCardOpened}
        isAutoExpand={isAutoExpand}
        alreadyCodedIcds={alreadyCodedIcds}
        dismissReasons={dismissReasons}
      />
    </div>
  );
};
