import './GapsContainer.less';

import {
  AlignEnum,
  AnalyticsHover,
  ColorNameEnum,
  SizeEnum,
  Text,
  Toast,
  WeightEnum,
} from '@getvim/atomic-ui';
import { BaseWidgetAnalyticsEventTypes, Encounter, UndoButtonState } from '@getvim/react-app-infra';
import { AppPatient, DiagnosisGap, EnrichedHcc, HCC } from '../../types';
import React, { useCallback, useContext, useEffect, useState } from 'react';
import { getNextNotTreatedGapIndex, sendVimChartItemClickAnalytic } from './logic';

import DiagnosisGapCard from '../diagnosis-gap-card/DiagnosisGapCard';
import { GET_ENRICHED_HCCS_QUERY } from '../../api/queries/getEnrichedHccs';
import { GlobalContext } from '../../contexts/globalContext';
import { diagnosisGapsLogger } from '../../logic/logger';
import { isEmpty } from 'lodash-es';
import { isValidHccCode } from '../../logic/validations';
import { useApolloClient } from '@apollo/client';
import useAutoResolveGaps from '../../hooks/useAutoResolveGaps';
import useGetDismissReasons from '../../hooks/useGetDismissReasons';
import { useVimOsMigrationAPI } from '@getvim-core-apps/vim-os-migration-api';
import { widgetId } from '../../consts';
import { analyticsManager } from '../../utils/analyticManager';

export interface GapsContainerProps {
  patient: AppPatient;
  gaps: DiagnosisGap[];
  encounter?: Encounter;
  updateNotficationsCount: (notificationsCountToUpdate: number) => void;
  treatedGaps: number[];
  setTreatedGaps: React.Dispatch<React.SetStateAction<number[]>>;
}

export type ModelToHccs = {
  [model: string]: string[];
};

const getInitializedUndoButtonState = (undoConfig, source): UndoButtonState => {
  if (undoConfig[source]) {
    return undoConfig[source];
  } else {
    diagnosisGapsLogger.warning('Unrecognize undo button state detected for source %s', source);

    const isAllSourcesNotSupported = Object.values(undoConfig).every(
      (state) => state === UndoButtonState.NOT_SUPPORTED,
    );
    if (isAllSourcesNotSupported || isEmpty(undoConfig)) return UndoButtonState.NOT_SUPPORTED;
    return UndoButtonState.SUPPORTED_DISABLED;
  }
};

const convertHccCodesToByModel = (hccs: HCC[]): ModelToHccs => {
  return hccs.reduce((modelToCode: ModelToHccs, { code, model }) => {
    if (!model) {
      return modelToCode;
    }
    if (!modelToCode[model]) {
      modelToCode[model] = [];
    }
    if (code && isValidHccCode(code)) {
      modelToCode[model].push(code);
    }
    return modelToCode;
  }, {});
};

const GapsContainer: React.FC<GapsContainerProps> = ({
  patient,
  gaps,
  encounter,
  updateNotficationsCount,
  treatedGaps,
  setTreatedGaps,
}: GapsContainerProps) => {
  const {
    platformActions: { isAppOpen },
  } = useVimOsMigrationAPI();

  const { undoConfig, documentViewerSupportedSources } = useContext(GlobalContext);
  const [isAppAlreadyOpened, setIsAppAlreadyOpened] = useState<boolean>(false);
  const [expandedGapPosition, setExpandedGapPosition] = useState<number>(1);
  const [isExpanded, setIsExpanded] = useState<boolean>(false);
  const [isManualExpanded, setIsManualExpanded] = useState<boolean>(false);
  const { Slide, ToastContainer } = Toast;
  const [expandedGap, setExpandedGap] = useState<DiagnosisGap>();
  const [sourceSupportsDocumentViewer, setSourceSupportsDocumentViewer] = useState<boolean>(false);
  const [getDismissReasons, dismissReasons] = useGetDismissReasons();
  const [isPerModelEnrichedIcdsLoading, setIsPerModelEnrichIcdsLoading] = useState<boolean>(true);
  const [enrichedHccs, setEnrichedHccs] = useState<EnrichedHcc[]>();
  const apolloClient = useApolloClient();

  const onToggle = (expanded: boolean, gap: DiagnosisGap) => {
    if (gap.position) {
      if (gap.position !== expandedGapPosition && expanded) {
        closeLastOpenedGap();
      }
      setIsExpanded(expanded);
      setExpandedGapPosition(gap.position);
      setIsManualExpanded(true);
    }
    sendVimChartItemClickAnalytic(gaps.length, gap, expanded ? 'open' : 'close', false);
  };

  const { setAutoResolveStatus, gapCardRefs, getGapAutoResolvedStatus } = useAutoResolveGaps(
    gaps,
    onToggle,
  );

  useEffect(() => {
    const getAllEnrichedHccs = async () => {
      setIsPerModelEnrichIcdsLoading(true);

      const hccs = gaps.map((gap) => gap.hcc);
      const hccsByModel = convertHccCodesToByModel(hccs);
      try {
        const enrichedIcdsFromHccsRaw = await Promise.all(
          Object.entries(hccsByModel).map(async ([model, hccCodes]) => {
            return (
              await apolloClient.query({
                query: GET_ENRICHED_HCCS_QUERY,
                fetchPolicy: 'no-cache',
                variables: {
                  input: {
                    hccCodes,
                    hccModel: model === 'unknown' ? undefined : model,
                  },
                },
              })
            ).data;
          }),
        );
        const enrichedIcdsFromHccs = enrichedIcdsFromHccsRaw.flatMap(
          (enrichedHcc) => enrichedHcc.getEnrichedHccs,
        );

        setEnrichedHccs(enrichedIcdsFromHccs);
      } catch (error) {
        diagnosisGapsLogger.error('an error ocurred while fetching enriched hccs', {
          error,
          hccsByModel,
        });
      }
      setIsPerModelEnrichIcdsLoading(false);
    };
    getAllEnrichedHccs();
  }, [gaps, apolloClient]);

  useEffect(() => {
    if (gaps.length > 0)
      getDismissReasons({
        variables: {
          input: { source: gaps[0].dataSource },
        },
      });
  }, [gaps, getDismissReasons]);

  useEffect(() => {
    gaps?.[0]?.dataSource &&
      setSourceSupportsDocumentViewer(documentViewerSupportedSources.includes(gaps[0].dataSource));
  }, [documentViewerSupportedSources, gaps]);

  useEffect(() => {
    if (gaps && isAppOpen && !isAppAlreadyOpened) {
      const firstExpandedGap = gaps[0];
      sendVimChartItemClickAnalytic(gaps.length, firstExpandedGap, 'open', true);
      setIsExpanded(true);
      setIsAppAlreadyOpened(true);
    }
  }, [gaps, isAppAlreadyOpened, isAppOpen]);

  const closeLastOpenedGap = () => {
    const lastExpandedGap = gaps.find((innerGap) => innerGap.position === expandedGapPosition);
    if (lastExpandedGap) {
      sendVimChartItemClickAnalytic(gaps.length, lastExpandedGap, 'close', true);
    }
  };

  const handleAutoExpandAnalytic = useCallback(
    (gap: DiagnosisGap) => {
      setIsManualExpanded(false);
      const gapToOpenIndex = getNextNotTreatedGapIndex(gaps, treatedGaps, gaps.length, gap);
      if (gap.position !== gapToOpenIndex) {
        if (isExpanded) {
          sendVimChartItemClickAnalytic(gaps.length, gap, 'close', true);
        }
        setExpandedGapPosition(gapToOpenIndex);
        const newGapToOpen = gaps.find((innerGap) => innerGap.position === gapToOpenIndex);
        if (newGapToOpen) {
          sendVimChartItemClickAnalytic(gaps.length, newGapToOpen, 'open', true);
        }
      }
    },
    [gaps, isExpanded, treatedGaps],
  );

  useEffect(() => {
    const notificationCount = gaps.length - treatedGaps.length;
    diagnosisGapsLogger.info('unresolved gaps count changed to', notificationCount);
    updateNotficationsCount(notificationCount);
  }, [treatedGaps.length, gaps.length, updateNotficationsCount]);

  useEffect(() => {
    if (expandedGap && expandedGap.position) setExpandedGapPosition(expandedGap.position);
  }, [expandedGap]);

  const onGapHandle = useCallback(
    (gap: DiagnosisGap, isUndo?: boolean, isAutoResolved?: boolean) => {
      if (isUndo) {
        const newTreatedGaps = [...treatedGaps];
        const filteredNewTreatedGaps = newTreatedGaps.filter(
          (treatedGapPosition: number) => treatedGapPosition !== gap.position,
        );
        diagnosisGapsLogger.info('update treated gaps after undo', {
          from: treatedGaps.length,
          to: filteredNewTreatedGaps.length,
        });
        setTreatedGaps(filteredNewTreatedGaps);
      } else if (isAutoResolved) {
        if (gap.position && treatedGaps.includes(gap.position)) return;

        setTreatedGaps((prevTreated) => {
          const newTreated = [...prevTreated, gap.position!];

          diagnosisGapsLogger.info('update treated gaps after auto-resolve', {
            from: prevTreated.length,
            to: newTreated.length,
            gapPosition: gap.position,
          });
          return newTreated;
        });
      } else if (gap.position) {
        if (treatedGaps.includes(gap.position)) return;
        diagnosisGapsLogger.info('update treated gaps to', {
          treatedGaps: treatedGaps.length + 1,
        });

        setTreatedGaps([...treatedGaps, gap.position]);
        if (gap.position) {
          handleAutoExpandAnalytic(gap);
        }
      }
    },
    [handleAutoExpandAnalytic, setTreatedGaps, treatedGaps],
  );

  const onHoverItem = (gap: DiagnosisGap) => {
    analyticsManager.track(BaseWidgetAnalyticsEventTypes.itemHover, {
      app_name: widgetId,
      position: gap.position,
      app_source_displayed: [gap.dataSource],
      content_supplier_patient_id: gap.sourcePatientId,
      hcc_code: gap.hcc.code,
      hcc_desc: gap.hcc.description,
    });
  };

  return (
    <div className="gapsContainer">
      <ToastContainer position="bottom-right" hideProgressBar autoClose={3000} transition={Slide} />
      {gaps.length > 0 ? (
        gaps.map((gap) => {
          gap.enrichedIcds = enrichedHccs?.find(
            (enrichedHcc) => enrichedHcc.code === gap.hcc.code,
          )?.icds;
          let keyAddition = '';

          if (gap.enrichedIcds?.length) {
            gap.diagnoses = gap.diagnoses.filter(
              (diagnosis) =>
                !gap.enrichedIcds?.some(
                  (icd) => icd.code === diagnosis?.icd?.code && !icd.billable,
                ),
            );
            keyAddition += '_with_enriched';
          }

          return (
            <div key={gap.id} ref={(element) => gapCardRefs.current.set(gap.position!, element)}>
              <AnalyticsHover
                key={`hover_${gap.entityId}`}
                onHoverAction={() => {
                  onHoverItem(gap);
                }}
              >
                <DiagnosisGapCard
                  patient={patient}
                  shouldExpandGap={expandedGapPosition === gap.position}
                  isManualOpen={expandedGapPosition === gap.position && isManualExpanded}
                  onGapHandle={onGapHandle}
                  key={gap.entityId + keyAddition}
                  gap={gap}
                  onToggle={onToggle}
                  encounter={encounter}
                  undoButtonState={getInitializedUndoButtonState(undoConfig, gap.dataSource)}
                  setExpandedGap={setExpandedGap}
                  sourceSupportsDocumentViewer={sourceSupportsDocumentViewer}
                  dismissReasons={dismissReasons}
                  isPerModelEnrichedIcdsLoading={isPerModelEnrichedIcdsLoading}
                  setAutoResolveStatus={setAutoResolveStatus}
                  getGapAutoResolvedStatus={getGapAutoResolvedStatus}
                />
              </AnalyticsHover>
            </div>
          );
        })
      ) : (
        <Text
          text="No information available"
          align={AlignEnum.left}
          size={SizeEnum['14px']}
          weight={WeightEnum.medium}
          colorName={ColorNameEnum.ultraDark}
          inline
        />
      )}
    </div>
  );
};

export { GapsContainer as default };
