import React, { FC } from 'react';
import { Button, ColorNameEnum, Text, WeightEnum } from '@getvim/atomic-ui';
import './ActionTitle.less';

interface ActionTitleProps {
  closeable?: boolean;
  onClose(): void;
}

export const ActionTitle: FC<ActionTitleProps> = ({ closeable = true, onClose, children }) => (
  <div className="action-title padding-h-20">
    <Text className="title-text" colorName={ColorNameEnum.theme} weight={WeightEnum.semibold}>
      {children}
    </Text>
    {closeable && (
      <Button
        buttonType="link"
        width="small"
        className="close-popover-btn"
        onClick={(event) => {
          event.stopPropagation();
          onClose();
        }}
      >
        <i className="icon-x i-va-fix-2" />
      </Button>
    )}
  </div>
);
