import { useApi } from '@getvim/internal-vim-os-sdk/react';
import { PushNotificationPayload } from '@getvim/internal-vim-os-sdk/types';
import { useCallback } from 'react';
import { diagnosisGapsLogger } from '../logic/logger';

export const useSdkNotifications = (isVimOs: boolean) => {
  const { pushNotification } = useApi();

  const notify = useCallback(
    (notificationConfig: PushNotificationPayload) => {
      if (!isVimOs) return;
      try {
        pushNotification.show(notificationConfig);
      } catch (error) {
        diagnosisGapsLogger.error('PI feature rollout - Failed to show auto-resolve notification', {
          error,
          notificationConfig: notificationConfig,
        });
      }
    },
    [pushNotification, isVimOs],
  );

  const hideNotification = useCallback(() => {
    if (!isVimOs) return;
    try {
      pushNotification.hide();
    } catch (error) {
      diagnosisGapsLogger.error('PI feature rollout - Failed to hide auto-resolve notification', {
        error,
      });
    }
  }, [pushNotification, isVimOs]);

  return { notify, hideNotification };
};
