import { ActionReason } from '../types';

export const getReason = (
  isAutoResolved: boolean,
  isWritebackSuccessful?: boolean,
): { reason: ActionReason } => {
  let action: ActionReason;
  if (isAutoResolved) {
    action = ActionReason.AUTO_RESOLVED;
  } else if (isWritebackSuccessful) {
    action = ActionReason.ADD;
  } else {
    action = ActionReason.AGREE_WITHOUT_WRITEBACK;
  }
  return {
    reason: action,
  };
};
