import { BaseWidgetAnalyticsEventTypes, BaseWidgetAnalyticsEvents } from '@getvim/react-app-infra';
import { Feature, GapBackground, GapSystem, ResourceType } from '../types';

import { AnalyticsClient } from '@getvim/utils-vim-connect-communication';
import { AxiosHeaderValue } from 'axios';
import { widgetId } from '../consts';
import { OpenedAppMethod } from '../app-level-analytics/useAppLevelAnalytics';

type ClickAction = 'open' | 'close';
type ClickTriggerType = 'automatic' | 'manual';
type SourceGapSystem = GapSystem | 'Hybrid';

export type AppAnalyticsBaseProperties = {
  vim_patient_id?: string | null;
  vim_insurer?: string | null;
  ehr_insurance?: string | null;
};

export enum DocumentViewerCloseReason {
  CLOSE = 'close',
  CANCEL = 'cancel',
  ERROR = 'error',
}

export type AutoResolveAppState = 'opened' | 'closed';

type VimChartItemClickProperties = {
  app_name: string;
  feature: Exclude<Feature, Feature.HEALTH_HISTORY | Feature.PRIOR_AUTH>;
  action: ClickAction;
  diagnosis_gaps_count: number;
  is_calender_view: boolean;
  action_method?: ClickTriggerType;
  auto_expand?: boolean;
  gap_background?: GapBackground;
  hcc_code: string; // Deprecated
  hcc_description?: string; // Deprecated
  gap_code?: string;
  gap_description?: string;
  gap_system: GapSystem;
  entity_id?: string;
  app_source_displayed?: string;
  content_supplier_patient_id?: string;
};

type DxGapActionClickedType = {
  app_name: string;
  position: number | undefined;
  app_source_displayed: string[];
  card_opened: boolean;
  auto_expand?: boolean;
  gap_background?: GapBackground;
  hcc_code: string; // Deprecated
  hcc_description?: string; // Deprecated
  gap_code?: string;
  gap_description?: string;
  gap_system: GapSystem;
  entity_id?: string;
  content_supplier_patient_id?: string;
};

type DxGapActionAgreeClickedType = DxGapActionClickedType & {
  app_name: string;
  auto_resolved: boolean;
  content_supplier_patient_id?: string;
};

type DxGapAgreeSubmittedDetails = {
  app_name: string;
  position: number | undefined;
  hcc_code: string; // Deprecated
  hcc_description: string | undefined; // Deprecated
  gap_code?: string;
  gap_description?: string;
  gap_system: GapSystem;
  selected_icd: (string | undefined)[];
  is_success: boolean;
  app_source_displayed: string[];
  auto_resolved: boolean;
  auto_resolved_app_state?: AutoResolveAppState | null;
  manually_written_icds: string[];
  gap_background?: GapBackground;
  entity_id?: string;
  content_supplier_patient_id?: string;
};

type DxGapDismissSubmittedDetails = {
  app_name: string;
  is_success: boolean;
  position: number | undefined;
  reason: string;
  app_source_displayed: string[];
  selected_icd: (string | undefined)[];
  manually_written_icds: string[];
  hcc_code?: string; // Deprecated
  hcc_description?: string; // Deprecated
  gap_background?: GapBackground;
  gap_code?: string;
  gap_description?: string;
  gap_system: GapSystem;
  entity_id?: string;
  content_supplier_patient_id?: string;
};

type DxGapsCalendarViewLoaded = {
  app_name: string;
  number_of_patients: number;
  number_of_patients_with_gaps: number;
  provider_name: string;
  date: string;
};

type DxGapsCalendarViewGoToEncounterClicked = {
  app_name: string;
  encounter_id: string;
  provider_name: string;
  vim_patient_id?: string;
};

type DxGapsCalendarViewPatientExpandClicked = {
  app_name: string;
  number_of_gaps: number;
  is_open: boolean;
  vim_patient_id?: string;
};

type DiagnosisGapsUndoActionClicked = {
  app_name: string;
  reversed_action: 'AGREE' | 'DISMISS';
  gap_position?: number;
  auto_resolved: boolean;
  gap_code?: string;
  gap_description?: string;
  gap_system: GapSystem;
  entity_id?: string;
  app_source_displayed: string;
  content_supplier_patient_id?: string;
};

type DiagnosisGapsDocumentOpened = {
  app_name: string;
  gap_code: string;
  gap_description?: string;
  gap_status?: string;
  card_opened: boolean;
  contain_highlights?: boolean;
  entity_id?: string;
  app_source_displayed: string;
};

type DiagnosisGapsDocumentClosed = {
  app_name: string;
  gap_code?: string;
  gap_description?: string;
  document_opened_for_time_seconds?: number;
  close_reason: DocumentViewerCloseReason;
  entity_id?: string;
  app_source_displayed: string;
};

type DiagnosisGapsDocumentLoaded = {
  app_name: string;
  gap_code?: string;
  contain_highlights?: boolean;
  loading_time?: string;
  document_extension?: string;
  tiff_logic?: string;
  file_size_mb?: string;
  file_content_type?: AxiosHeaderValue;
};

type DiagnosisGapsDocumentFetchFailed = {
  app_name: string;
  gap_code?: string;
};

export type VimChartAnalyticsEvents = BaseWidgetAnalyticsEvents & {
  diagnosis_gaps_app_enabled: {
    app_name: string;
    vim_patient_id?: string;
    content_supplier_patient_id?: string;
    app_source_enabled: string[];
    app_source_displayed: string[] | undefined;
    items_received_count: number;
    encounter_id?: string;
    encounter_date?: string;
    items_received: {
      entity_id?: string;
      position?: number;
      code: string;
      description?: string;
      gapBackground?: GapBackground;
      gap_system: GapSystem;
      gap_model?: string;
    }[];
    execution_time?: number;
    has_document?: boolean;
    source_gaps_system: SourceGapSystem;
  };
  [BaseWidgetAnalyticsEventTypes.itemHover]: BaseWidgetAnalyticsEvents[BaseWidgetAnalyticsEventTypes.itemHover] & {
    hcc_code: string;
    hcc_desc: string | undefined;
  };
  vim_chart_category_click: { feature: Feature; action: ClickAction; type: ClickTriggerType };
  vim_chart_item_click: VimChartItemClickProperties;
  vim_chart_health_history_page_view: {
    pageNumber: number;
    pagesAmount: number;
    filtered_resource: ResourceType;
  };
  gaps_fetched: {
    app_name: string;
    app_source_displayed: string[];
    gaps_count: number;
    gaps_received: {
      position?: number;
      code: string;
      description?: string;
    }[];
  };
  patient_match: {
    app_name: string;
    vim_patient_id?: string;
    content_supplier_patient_id: string;
    organiztion_id: number;
    content_supplier: string;
  };
  dx_gap_agree_clicked: DxGapActionAgreeClickedType;
  dx_gap_dismiss_clicked: DxGapActionClickedType;
  dx_gap_agree_submitted: DxGapAgreeSubmittedDetails;
  dx_gap_dismiss_submitted: DxGapDismissSubmittedDetails;
  dx_gaps_calendar_view_loaded: DxGapsCalendarViewLoaded;
  dx_gaps_calendar_view_go_to_encounter_clicked: DxGapsCalendarViewGoToEncounterClicked;
  dx_gaps_calendar_view_patient_expand_clicked: DxGapsCalendarViewPatientExpandClicked;
  dx_undo_action_clicked: DiagnosisGapsUndoActionClicked;
  dx_document_opened: DiagnosisGapsDocumentOpened;
  dx_document_closed: DiagnosisGapsDocumentClosed;
  dx_document_loaded: DiagnosisGapsDocumentLoaded;
  dx_document_fetch_failed: DiagnosisGapsDocumentFetchFailed;
  diagnosis_gaps_app_opened: {
    app_name: string;
    vim_patient_id?: string;
    app_open_method: OpenedAppMethod;
  };
};

export const analyticsClient = new AnalyticsClient<VimChartAnalyticsEvents>(widgetId);
