import { gqlClient } from '@getvim/vim-connect/src/infra/common/gql-client';
import { calculateServiceUrl } from '../api/appEnv';
import { GraphqlClient } from '../api/graphql-client';
import { CDE_REQUEST_TRIGGER_QUERY } from '../api/queries/cdeRequestTrigger';
import { diagnosisGapsLogger } from '../logic/logger';
import {
  AppPatient,
  CdeRequestTrigger,
  PatientSourceDetails,
  TriggerByAppType,
  TriggerType,
} from '../types/index';

const MAX_CACHE_SIZE = 1000;

export const handleCdeRequestTrigger = async ({
  patient,
  dataSource,
  encounterId,
  encounterDate,
  orgId,
  triggerType,
  cache,
  setCache,
  shouldUseSourceVaultTokens,
}: {
  patient?: AppPatient;
  dataSource: string;
  encounterId?: string;
  encounterDate?: string;
  orgId: number;
  triggerType: TriggerType;
  cache: Set<string>;
  setCache: React.Dispatch<React.SetStateAction<Set<string>>>;
  shouldUseSourceVaultTokens: boolean;
}) => {
  try {
    if (!encounterDate || !encounterId) {
      diagnosisGapsLogger.info('encounter data is missing, skip cde trigger', { encounterId });
      return;
    }

    const sourceVaultToken = patient?.patientSourceVaultTokens?.find(
      (sourceVaultToken) => sourceVaultToken.source === dataSource,
    )?.sourceVaultToken;
    const contentSupplierId = shouldUseSourceVaultTokens
      ? sourceVaultToken
      : patient?.contentSupplierIdentifiers?.[dataSource]?.contentSupplierId;
    const memberToken = patient?.contentSupplierIdentifiers?.[dataSource]?.memberToken;
    const patientToken = patient?.token;

    if (!contentSupplierId || !patientToken) {
      diagnosisGapsLogger.error('patient data is missing, skip cde trigger', { patient });
    }

    const contentSupplierIdentifiers: PatientSourceDetails = {
      contentSupplier: dataSource,
      contentSupplierId: contentSupplierId,
      memberToken: memberToken,
      patientToken: patientToken,
    };

    const gapsEventInput = {
      triggerType: triggerType,
      orgId: orgId,
      encounterId,
      encounterDate: new Date(encounterDate).toISOString(),
      triggeredByApp: TriggerByAppType.DIAGNOSIS_GAPS,
    };
    const requestId = getRequestCacheKey(gapsEventInput);
    if (!cache.has(requestId)) {
      const serviceUrl = await calculateServiceUrl({ serviceName: 'gaps', localPort: 7000 });
      const gapsBFFClient = gqlClient;
      gapsBFFClient.setAccessToken(GraphqlClient.getAccessToken());
      diagnosisGapsLogger.info('sending cde trigger request', {
        contentSupplierIdentifiers: contentSupplierIdentifiers,
        gapsEventInput: gapsEventInput,
      });
      await gapsBFFClient.queryAuthenticated<
        { cdeRequestTrigger: void },
        { input: CdeRequestTrigger }
      >({
        context: {
          uri: `${serviceUrl}/api/graphql`,
        },
        query: CDE_REQUEST_TRIGGER_QUERY(),
        variables: {
          input: {
            contentSupplierIdentifiers: contentSupplierIdentifiers,
            gapsEventInput: gapsEventInput,
          },
        },
        fetchPolicy: 'no-cache',
      });
      setCache((prevCache) => {
        if (prevCache.size > MAX_CACHE_SIZE) {
          const keys = Array.from(prevCache.keys());
          prevCache.delete(keys[0]);
        }
        const newCache = new Set(prevCache.add(requestId));
        return newCache;
      });
      diagnosisGapsLogger.info('cde trigger added to cache', { requestId });
    } else {
      diagnosisGapsLogger.info('cde trigger already sent', { requestId });
    }
  } catch (error) {
    diagnosisGapsLogger.error('Unexpected error during handling cde trigger', { error });
  }
};

const getRequestCacheKey = (gapsEventInput) => {
  return `${gapsEventInput.orgId}-${gapsEventInput.encounterId}`;
};
