import { ActionReasonInput, DiagnosisGap, DiagnosisGapActionStatus, ICD } from '../types';

import DIAGNOSIS_GAP_FEEDBACK_MUTATION from '../api/mutations/diagnosisGapsFeedback';
import { Encounter } from '@getvim/react-app-infra';
import dayjs from 'dayjs';
import { diagnosisGapsLogger } from '../logic/logger';
import { useMutation } from '@apollo/client';
import { widgetId } from '../consts';
import { useCallback, useContext } from 'react';
import { GlobalContext } from '../contexts/globalContext';
import { extractPatientSourceVaultToken } from '@getvim-core-apps/organizations';
import { analyticsManager } from '../utils/analyticManager';

type diagnosisGapsHookFeedbackInput = {
  patient: any;
  gap: DiagnosisGap;
  selectedIcds: ICD[];
  encounter?: Encounter;
  action: DiagnosisGapActionStatus;
  actionReason: ActionReasonInput;
  onCompleted?: () => void;
  onError?: (error) => void;
};

type UseFeedback = [
  diagnosisGapsFeedback: ({
    patient,
    gap,
    selectedIcds,
    encounter,
    action,
    actionReason,
    onCompleted,
    onError,
  }: diagnosisGapsHookFeedbackInput) => Promise<void>,
];

export default function useFeedback(): UseFeedback {
  const [diagnosisGapsFeedback] = useMutation(DIAGNOSIS_GAP_FEEDBACK_MUTATION);
  const { shouldUseSourceVaultTokens } = useContext(GlobalContext);

  const sendFeedback = useCallback(
    async ({
      patient,
      gap,
      selectedIcds,
      encounter,
      action,
      actionReason,
      onCompleted,
      onError,
    }: diagnosisGapsHookFeedbackInput): Promise<void> => {
      const { demographics, insurance, patientSourceVaultTokens, vimPatientId } = patient;
      const { address } = demographics || {};
      const { reason, reasonDescription } = actionReason;
      const { hcc } = gap;

      const sourceVaultToken = extractPatientSourceVaultToken(
        patientSourceVaultTokens,
        gap.dataSource,
      )?.sourceVaultToken;

      const input = {
        sourcePatientId: gap.sourcePatientId,
        ...(shouldUseSourceVaultTokens
          ? { sourceVaultToken, vimPatientId }
          : {
              patient: {
                vimPatientId: patient?.vimPatientId,
                patientId: patient?.patientId,
                mrn: patient?.mrn,
                firstName: demographics?.firstName,
                middleName: demographics?.middleName,
                lastName: demographics?.lastName,
                dateOfBirth: demographics?.dateOfBirth,
                memberId: insurance?.memberId,
                insurer: insurance?.insurer,
                address: {
                  fullAddress: address?.fullAddress,
                  address1: address?.address1,
                  address2: address?.address2,
                  city: address?.city,
                  state: address?.state,
                  zipCode: address?.zipCode,
                },
              },
            }),
        gap: {
          gapId: gap?.gapId,
          entityId: gap?.entityId,
          gapSystem: gap.gapSystem,
          gapCode: gap.gapCode,
          gapDescription: gap.gapDescription,
          hccCode: hcc.code,
          hccDescription: hcc.description,
          icds: selectedIcds.map((icd) => ({ icdCode: icd.code, icdDescription: icd.description })),
        },
        feedback: {
          action,
          reason,
          reasonDescription,
        },
        dataSource: gap.dataSource,
        encounterDate: encounter?.encounterDate
          ? dayjs(encounter.encounterDate).format('YYYY-MM-DD')
          : undefined,
        encounterId: encounter?.encounterId,
        providerNPI: encounter?.provider?.npi,
      };
      await diagnosisGapsFeedback({
        variables: { input },
        fetchPolicy: 'no-cache',
        onCompleted: () => {
          onCompleted?.();
        },
        onError: (error) => {
          diagnosisGapsLogger.info('An error occoured when diagnosisGapsFeedback', { error });
          if (onError) {
            onError(error);
          }
        },
      });
    },
    [diagnosisGapsFeedback, shouldUseSourceVaultTokens],
  );

  return [sendFeedback];
}

const getAutoResolveAppState = (isAppOpen?: boolean) => {
  if (isAppOpen === undefined) return null;
  return isAppOpen ? 'opened' : 'closed';
};

export const sendGapAgreeSubmittedAnalytic = (
  {
    gap,
    isSuccess,
    selectedIcds,
    isAutoResolved = false,
    manuallyWrittenIcds = [],
  }: {
    gap: DiagnosisGap;
    isSuccess: boolean;
    selectedIcds: ICD[];
    isAutoResolved?: boolean;
    manuallyWrittenIcds?: string[];
  },
  isAppOpen?: boolean,
) => {
  analyticsManager.track('dx_gap_agree_submitted', {
    hcc_code: gap.hcc.code,
    hcc_description: gap.hcc?.description,
    gap_code: gap.gapCode,
    gap_description: gap.gapDescription,
    gap_system: gap.gapSystem,
    selected_icd: selectedIcds.map((icd) => icd.code),
    is_success: isSuccess,
    app_source_displayed: [gap.dataSource],
    position: gap.position,
    auto_resolved: isAutoResolved,
    auto_resolved_app_state: getAutoResolveAppState(isAppOpen),
    manually_written_icds: manuallyWrittenIcds,
    gap_background: gap?.gapBackground,
    entity_id: gap.entityId,
    content_supplier_patient_id: gap.sourcePatientId,
    app_name: widgetId,
  });
};

export const sendGapDismissSubmittedAnalytic = ({
  reason,
  gap,
  isSuccess,
  manuallyWrittenIcds = [],
}: {
  reason: ActionReasonInput;
  gap: DiagnosisGap;
  isSuccess: boolean;
  manuallyWrittenIcds?: string[];
}) => {
  const { reason: actionReason } = reason;
  analyticsManager.track('dx_gap_dismiss_submitted', {
    reason: actionReason,
    position: gap.position,
    is_success: isSuccess,
    app_source_displayed: [gap.dataSource],
    gap_background: gap.gapBackground,
    selected_icd:
      gap.diagnoses && gap.diagnoses.some((diagnose) => diagnose?.icd?.code)
        ? gap.diagnoses.map((diagnose) => diagnose?.icd?.code)
        : [],
    manually_written_icds: manuallyWrittenIcds,
    hcc_code: gap.hcc?.code,
    hcc_description: gap.hcc?.description,
    gap_code: gap.gapCode,
    gap_description: gap.gapDescription,
    gap_system: gap.gapSystem,
    entity_id: gap.entityId,
    content_supplier_patient_id: gap.sourcePatientId,
    app_name: widgetId,
  });
};
