import { AlignEnum, Loader, SizeEnum, Text } from '@getvim/atomic-ui';
import React, { FC } from 'react';
import { UndoButtonState } from '@getvim/react-app-infra';
import {
  DiagnosisGap,
  DiagnosisGapActionStatus,
  DismissReason,
  FeedbackActions,
  ReasonAction,
} from '../../types';
import '../DiagnosisGap/DiagnosisGap.less';
import './DiagnosisGapStatusMessage.less';

import UndoButton from '../undo-button/UndoButton';
import { CardState } from '../diagnosis-gap-card/DiagnosisGapCard';

interface StatusMessageProps {
  status: DiagnosisGapActionStatus;
  manualAddToChart?: boolean;
  dismissReason?: ReasonAction;
  onClickUndo: (action: FeedbackActions) => Promise<void>;
  cardState: CardState;
  gap: DiagnosisGap;
  undoButtonState: UndoButtonState;
  isActionLoading: boolean;
}
const renderMessage = (status, cardState, gap, manualAddToChart) => {
  if (status === DiagnosisGapActionStatus.ADD && !cardState.isUndoClicked) {
    if (cardState.isAutoResolved && !(gap.actionReversed && gap.reason === 'AUTO_RESOLVED')) {
      return <AutoResolvedMessage gap={gap} />;
    }
    if (manualAddToChart) {
      return <ManualAddToChartMessage />;
    }
    return <SuccessMessage />;
  }
  return null;
};
/* eslint-disable no-nested-ternary */
export const DiagnosisGapStatusMessage: FC<StatusMessageProps> = ({
  status,
  manualAddToChart = false,
  dismissReason,
  onClickUndo,
  cardState,
  gap,
  undoButtonState,
  isActionLoading,
}) => {
  if (isActionLoading) {
    return (
      <div className="gap-status-bar">
        <Loader type="dots" size="small" padding="none" />
      </div>
    );
  }

  return (
    <div className="action-result-bar">
      {status === DiagnosisGapActionStatus.DISMISS ? (
        <DismissedCodingGapMessage dismissReason={dismissReason as ReasonAction} />
      ) : null}
      {renderMessage(status, cardState, gap, manualAddToChart)}
      {!cardState.isUndoClicked ? (
        <UndoButton
          undoButtonState={undoButtonState}
          onClick={async () => {
            await onClickUndo(
              status === DiagnosisGapActionStatus.DISMISS
                ? FeedbackActions.DISMISS
                : FeedbackActions.AGREE,
            );
          }}
        />
      ) : null}
    </div>
  );
};

export const StatusMessage: FC<{ className: string; iconClass: string }> = ({
  children,
  iconClass,
  className,
}) => {
  return (
    <div className={`status-message ${className}`}>
      <Text className="message-text" size={SizeEnum['12px']} align={AlignEnum.left}>
        <i className={`${iconClass} inline-block`} />
        {children}
      </Text>
    </div>
  );
};

const DismissedCodingGapMessage: FC<{
  dismissReason?: StatusMessageProps['dismissReason'];
}> = ({ dismissReason }) => {
  return (
    <StatusMessage className="confirmation-messages" iconClass="icon-x dismiss">
      Gap dismissed {dismissReason?.displayName ? ` (${dismissReason?.displayName})` : ''}{' '}
    </StatusMessage>
  );
};

export const InProgressGap: FC<{
  onClickUndo: (action: FeedbackActions) => Promise<void>;
  gap: DiagnosisGap;
  undoButtonState: UndoButtonState;
  dismissReasons?: DismissReason[];
}> = ({ onClickUndo, undoButtonState, gap, dismissReasons }) => {
  const { feedbackAction, feedbackReason } = gap;
  const dismissFeedbackReason = dismissReasons?.find(
    (reason) => reason.reasonCode === feedbackReason,
  );
  return (
    <div className="action-result-bar">
      {feedbackAction === FeedbackActions.DISMISS ? (
        <DismissedCodingGapMessage
          dismissReason={dismissFeedbackReason as ReasonAction | undefined}
        />
      ) : feedbackReason === 'AUTO_RESOLVED' ? (
        <AutoResolvedMessage gap={gap} />
      ) : (
        <StatusMessage className="confirmation-messages" iconClass="icon-check">
          {'Gap accepted.'}
        </StatusMessage>
      )}
      <UndoButton
        undoButtonState={undoButtonState}
        onClick={async () => await onClickUndo(feedbackAction!)}
      />
    </div>
  );
};

export const SuccessMessage = () => {
  return (
    <StatusMessage className="confirmation-messages" iconClass="icon-check">
      Gap accepted. Please validate the accuracy of the added diagnosis to the note
    </StatusMessage>
  );
};

const ManualAddToChartMessage = () => (
  <StatusMessage className="manual-add-to-chart" iconClass="icon-hourglass-bottom">
    Gap accepted (diagnosis should be added to the note manually)
  </StatusMessage>
);

const AutoResolvedMessage = ({ gap }) => (
  <StatusMessage className="auto-resolved-gap" iconClass="icon-auto-resolved">
    Gap automatically accepted based on patient’s documented conditions (ICD&#8209;10 codes: &nbsp;
    {gap.diagnoses.map((diagnose) => diagnose.id).join(', ')})
  </StatusMessage>
);
