import { Tooltip } from '@getvim/atomic-ui';
import React, { FC } from 'react';

export const DocumentViewerButton: FC<{
  shouldDisable: boolean;
  onClick(): void;
}> = ({ shouldDisable, onClick }) => {
  return (
    <Tooltip
      placement="top"
      tooltipContent={
        shouldDisable ? 'No supporting document available' : 'View supporting document'
      }
      bgColor="light"
    >
      <button
        type="button"
        className="document-view-button"
        disabled={shouldDisable}
        onClick={(event) => {
          event.stopPropagation();
          onClick();
        }}
      >
        <i className="icon-view-document text-24" />
      </button>
    </Tooltip>
  );
};
