import React, { FC } from 'react';
import { Button, Text } from '@getvim/atomic-ui';
import './ActionButton.less';

interface ActionButtonProps {
  onClick(): void;
  disabled?: boolean;
  isLocked?: boolean;
  tooltipText?: string;
  showTooltip?: boolean;
}

export const ActionButton: FC<ActionButtonProps> = ({
  onClick,
  disabled,
  isLocked,
  children,
  tooltipText,
  showTooltip = true,
}) => {
  let toolTipMessage = encounterStatusToMessage.outsideAnExam;
  if (isLocked) {
    toolTipMessage = encounterStatusToMessage.encounterLocked;
  }
  if (tooltipText) {
    toolTipMessage = tooltipText;
  }

  return (
    <div className="diagnosis-gap-action-button">
      <Button
        className="action-btn"
        buttonType="tiny"
        bgColor="themedOutline"
        disabled={disabled || !!isLocked}
        width="block"
        onClick={(event) => {
          onClick();
          event.stopPropagation();
        }}
      >
        {children}
      </Button>
      {showTooltip && <Text className="action-tooltip" text={toolTipMessage} />}
    </div>
  );
};

const encounterStatusToMessage = {
  outsideAnExam: 'Action available during an exam',
  encounterLocked: 'Please make sure the assessment is accessible and editable',
};
