import React from 'react';
import { SizeEnum, Text } from '@getvim/atomic-ui';

import './index.less';

interface ApplicationTitleProp {
  title: string;
  notifications?: number;
}

export function ApplicationTitle({ title, notifications }: ApplicationTitleProp) {
  return (
    <div className="application-title">
      <Text className="label" size={SizeEnum['14px']}>
        <b>{title}</b> {!!notifications && `(${notifications})`}
      </Text>
    </div>
  );
}
