import axios, { ResponseType, RawAxiosResponseHeaders, AxiosResponseHeaders } from 'axios';
import { useEffect, useState } from 'react';

type UseAxiosResponse = [
  loaded: boolean,
  data?: any,
  headers?: RawAxiosResponseHeaders | AxiosResponseHeaders,
  error?: any,
];

const useAxios = (url?: string, responseType?: ResponseType): UseAxiosResponse => {
  const [data, setData] = useState<any>();
  const [headers, setHeaders] = useState<RawAxiosResponseHeaders | AxiosResponseHeaders>();
  const [error, setError] = useState();
  const [loaded, setLoaded] = useState<boolean>(false);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const { data, headers } = await axios.get(url!, {
          responseType,
        });

        setData(data);
        setHeaders(headers);
      } catch (error: any) {
        setError(error.message);
      } finally {
        setLoaded(true);
      }
    };

    if (url) {
      fetchData();
    }
  }, [url, responseType]);

  return [loaded, data, headers, error];
};

export default useAxios;
