import { Button, Tooltip } from '@getvim/atomic-ui';
import React, { FC } from 'react';
import './UndoButton.less';
import { UndoButtonState } from '@getvim/react-app-infra';

const getDisabledTooltip = (undoButtonState: UndoButtonState) => {
  if (undoButtonState === UndoButtonState.SUPPORTED_DISABLED) {
    return 'Undo action is not supported by current data source';
  }
  if (undoButtonState === UndoButtonState.SUPPORTED_DISABLED_TIMEOUT) {
    return 'Reverting actions is possible up to 1 hour post-submission';
  }
  if (undoButtonState === UndoButtonState.OUT_OF_EXAM) {
    return 'Action available during an exam';
  }
};

const UndoButton: FC<{ onClick(): void; undoButtonState: UndoButtonState }> = ({
  onClick,
  undoButtonState,
}) => {
  const shouldDisable = [
    UndoButtonState.SUPPORTED_DISABLED,
    UndoButtonState.SUPPORTED_DISABLED_TIMEOUT,
    UndoButtonState.OUT_OF_EXAM,
  ].includes(undoButtonState);
  const undoButton = (
    <Button
      className="gap-undo-button"
      buttonType="tiny"
      bgColor="themedOutline"
      onClick={onClick}
      disabled={shouldDisable}
    >
      Undo
    </Button>
  );
  return (
    <>
      {shouldDisable ? (
        <Tooltip
          className="undo-button-tooltip"
          tooltipContent={getDisabledTooltip(undoButtonState)}
          bgColor="light"
        >
          {undoButton}
        </Tooltip>
      ) : (
        undoButton
      )}
    </>
  );
};

export default UndoButton;
