import { useVimOsMigrationAPI } from '@getvim-core-apps/vim-os-migration-api';
import { ButtonGroupComponent } from '@getvim/atomic-ui';
import React, { FC, useContext, useState } from 'react';
import { GlobalContext } from '../../contexts/globalContext';
import {
  AppPatient,
  DiagnosisGap,
  DiagnosisGapActionStatus,
  DismissReason,
  Feature,
  ICD,
  ReasonAction,
  TriggerType,
} from '../../types';
import { ActionButton } from '../ActionButton/ActionButton';
import { ActionTitle } from '../ActionTitle/ActionTitle';
import { DataLoader } from '../DataLoader/DataLoader';
import { DiagnosisGapActionPopover } from '../DiagnosisGapActionPopover/DiagnosisGapActionPopover';
import { FailureScreen } from '../FailureScreen/FailureScreen';
import useFeedback, { sendGapDismissSubmittedAnalytic } from '../../hooks/useFeedback';
import { diagnosisGapsLogger } from '../../logic/logger';
import { handleCdeRequestTrigger } from '../../logic/gapsCdeTrigger';
import './DismissPopover.less';
import { widgetId } from '../../consts';
import { analyticsManager } from '../../utils/analyticManager';

interface DismissPopoverProps {
  patient: AppPatient | undefined;
  gap: DiagnosisGap;
  disabled: boolean;
  isLocked?: boolean;
  isCardOpened: boolean;
  isAutoExpand?: boolean;
  alreadyCodedIcds: string[];
  dismissReasons?: DismissReason[];

  onDismissSuccess(reason: ReasonAction): void;
}

const isReasonHasMandatoryDescription = (dismissReason: DismissReason | undefined): boolean =>
  !!dismissReason?.isFreeTextRequired;

const isDismissPopoverConfirmDisabled = (
  reason: DismissReason | undefined,
  description: string,
): boolean => {
  if (!reason) return true;
  if (!isReasonHasMandatoryDescription(reason)) return false;
  return !description;
};

const onFeedbackError = (
  error: any,
  data: {
    gap: DiagnosisGap;
    reason: ReasonAction;
    alreadyCodedIcds: string[];
    selectedIcd: ICD[];
  },
) => {
  const { gap, reason, alreadyCodedIcds, selectedIcd } = data;
  sendGapDismissSubmittedAnalytic({
    reason: { reason: reason.reason, reasonDescription: reason.description },
    gap,
    isSuccess: false,
    manuallyWrittenIcds: alreadyCodedIcds,
  });

  diagnosisGapsLogger.error('Failed to mark coding gap as dismissed!', {
    entityId: gap.entityId,
    selectedIcd,
    error,
  });
};

export const DismissPopover: FC<DismissPopoverProps> = ({
  patient,
  gap,
  onDismissSuccess,
  disabled,
  isLocked,
  isCardOpened,
  isAutoExpand,
  alreadyCodedIcds,
  dismissReasons,
}) => {
  const {
    ehrState: { encounter },
  } = useVimOsMigrationAPI();

  const { dataSource, position } = gap;
  const [popoverShown, setPopoverShown] = useState<boolean>(false);
  const [dismissFailed, setDismissFailed] = useState<boolean>(false);
  const [loading, setLoading] = useState<boolean>(false);
  const [isButtonClicked, setIsButtonClicked] = useState<boolean>(false);

  const [sendDiagnosisGapsFeedback] = useFeedback();
  const {
    cdeTriggerCache,
    setCdeTriggerCache,
    cdeTriggerSupportedSources,
    shouldUseSourceVaultTokens,
  } = useContext(GlobalContext);
  const { config } = useVimOsMigrationAPI();

  const onCompleted = (reason: ReasonAction): void => {
    if (cdeTriggerSupportedSources[dataSource]?.includes(TriggerType.GAP_REJECTED)) {
      handleCdeRequestTrigger({
        shouldUseSourceVaultTokens,
        patient,
        dataSource,
        encounterId: encounter?.encounterId,
        encounterDate: encounter?.encounterDate,
        orgId: config.organization.id,
        triggerType: TriggerType.GAP_REJECTED,
        cache: cdeTriggerCache,
        setCache: setCdeTriggerCache,
      });
    }
    sendGapDismissSubmittedAnalytic({
      reason: { reason: reason.reason, reasonDescription: reason.description },
      gap,
      isSuccess: true,
      manuallyWrittenIcds: alreadyCodedIcds,
    });
    onDismissSuccess(reason);
  };

  async function onDismiss(reason: ReasonAction) {
    setLoading(true);
    try {
      const selectedIcd = gap.diagnoses.map((diagnosis) => diagnosis.icd!).filter(Boolean);

      await sendDiagnosisGapsFeedback({
        patient,
        gap,
        selectedIcds: selectedIcd,
        encounter,
        action: DiagnosisGapActionStatus.DISMISS,
        actionReason: { reason: reason.reason, reasonDescription: reason?.description },
        onCompleted: () => onCompleted(reason),
        onError: (error) =>
          onFeedbackError(error, {
            gap,
            reason,
            alreadyCodedIcds,
            selectedIcd,
          }),
      });
    } catch {
      setDismissFailed(true);
    } finally {
      setLoading(false);
    }
  }

  const onPopoverClosed = () => {
    setPopoverShown(false);
    setIsButtonClicked(false);
  };

  const onPopoverOpen = () => {
    if (!isCardOpened && !isAutoExpand) {
      analyticsManager.track('vim_chart_item_click', {
        feature: Feature.CODING_GAPS,
        action: 'open',
        diagnosis_gaps_count: 0,
        is_calender_view: false,
        action_method: 'automatic',
        auto_expand: isAutoExpand,
        gap_background: gap.gapBackground,
        hcc_code: gap.hcc.code,
        hcc_description: gap.hcc.description,
        gap_code: gap.gapCode,
        gap_description: gap.gapDescription,
        gap_system: gap.gapSystem,
        entity_id: gap.entityId,
        app_source_displayed: gap.dataSource,
        content_supplier_patient_id: gap.sourcePatientId,
        app_name: widgetId,
      });
    }
    analyticsManager.track('dx_gap_dismiss_clicked', {
      position,
      app_source_displayed: [gap.dataSource],
      card_opened: isCardOpened,
      auto_expand: isAutoExpand,
      gap_background: gap.gapBackground,
      hcc_code: gap.hcc.code,
      hcc_description: gap.hcc.description,
      gap_code: gap.gapCode,
      gap_description: gap.gapDescription,
      gap_system: gap.gapSystem,
      entity_id: gap.entityId,
      content_supplier_patient_id: gap.sourcePatientId,
      app_name: widgetId,
    });
    setIsButtonClicked(true);
    setPopoverShown(true);

    if (!dismissReasons?.length) {
      onDismiss({ displayName: '', reason: '' });
    }
  };

  return (
    <DiagnosisGapActionPopover
      disabled={disabled || isButtonClicked}
      onShow={onPopoverOpen}
      onClose={onPopoverClosed}
      shown={popoverShown}
      isLocked={isLocked}
      shouldShowTooltip={!isButtonClicked && disabled}
      buttonText="Dismiss"
    >
      <div className="dismiss-content">
        <ActionTitle onClose={onPopoverClosed}>Dismiss reason</ActionTitle>
        <DismissPopoverContent
          onClose={onPopoverClosed}
          onDismiss={onDismiss}
          loading={loading}
          dismissFailed={dismissFailed}
          dataSource={dataSource}
          dismissReasons={dismissReasons}
        />
      </div>
    </DiagnosisGapActionPopover>
  );
};

interface DismissPopoverContentProps {
  loading: boolean;
  dismissFailed: boolean;
  dataSource: string;
  dismissReasons?: DismissReason[];

  onClose(): void;

  onDismiss(reason: ReasonAction): void;
}

const DismissPopoverContent: FC<DismissPopoverContentProps> = ({
  loading,
  onClose,
  dismissFailed,
  onDismiss,
  dataSource,
  dismissReasons,
}) => {
  if (loading) return <DataLoader />;
  if (dismissFailed)
    return (
      <FailureScreen onClose={onClose} text="Unfortunately we cannot dismiss this diagnosis." />
    );
  return (
    <DismissSelectionDialog
      onCancel={onClose}
      onDismiss={onDismiss}
      dataSource={dataSource}
      dismissReasons={dismissReasons}
    />
  );
};
const DismissSelectionDialog: FC<{
  onCancel(): void;
  onDismiss(reason: ReasonAction): void;
  dataSource: string;
  dismissReasons?: DismissReason[];
}> = ({ onCancel, onDismiss, dismissReasons }) => {
  const [selectedReason, setSelectedReason] = useState<DismissReason | undefined>(undefined);
  const [descriptionReason, setDescriptionReason] = useState('');

  return (
    <>
      <ButtonGroupComponent
        items={
          dismissReasons?.map(({ reasonCode, displayName }) => ({
            value: reasonCode,
            text: displayName,
            textInputValue: descriptionReason,
          })) ?? []
        }
        value={selectedReason?.reasonCode as any}
        width="block"
        color="extraDarkGray"
        buttonType="dropdownOption"
        direction="column"
        maxLength={255}
        textInputPlaceholder={
          isDismissPopoverConfirmDisabled(selectedReason, descriptionReason)
            ? 'Enter additional reason (required)'
            : 'Enter additional reason'
        }
        onChange={(reason: string) => {
          setDescriptionReason('');
          const dismissReasonObject: DismissReason | undefined = dismissReasons?.find(
            (dismissReason) => dismissReason.reasonCode === reason,
          );
          setSelectedReason(
            reason !== selectedReason?.reasonCode ? dismissReasonObject : undefined,
          );
        }}
        onTextInputChange={(description: string) => {
          setDescriptionReason(description);
        }}
        multiLines
        showTextInput
        shouldUseAutoSizeInput
      />
      <ConfirmationBar
        onConfirm={() => {
          if (selectedReason?.reasonCode) {
            onDismiss({
              description: descriptionReason,
              reason: selectedReason.reasonCode,
              displayName: selectedReason.displayName,
            });
          }
        }}
        onCancel={onCancel}
        disabled={isDismissPopoverConfirmDisabled(selectedReason, descriptionReason)}
      />
    </>
  );
};

const ConfirmationBar: FC<{
  onCancel(): void;
  onConfirm(): void;
  disabled: boolean;
}> = ({ onConfirm, disabled, onCancel }) => (
  <div className="popover-footer text-center">
    <div className="dismiss-footer">
      <div className="diagnosis-gap-action-bar">
        <ActionButton
          onClick={onConfirm}
          disabled={disabled}
          tooltipText="You have to choose a reason"
          showTooltip={disabled}
        >
          {'Confirm'}
        </ActionButton>
        <ActionButton onClick={onCancel}>Close</ActionButton>
      </div>
    </div>
  </div>
);
