import { AutoResolveGapStatus, DiagnosisGap } from '../types';
import { ButtonStyle, PushNotificationPayload } from '@getvim/internal-vim-os-sdk/types';
import { useCallback, useEffect, useRef, useState } from 'react';

import { autoResolveNotification } from '../consts';
import { diagnosisGapsLogger } from '../logic/logger';
import { isEmpty } from 'lodash-es';
import { useSdkNotifications } from './useSdkNotifications';
import { useVimOsMigrationAPI } from '@getvim-core-apps/vim-os-migration-api';
import { v4 as uuidv4 } from 'uuid';

export default function useAutoResolveGaps(
  gaps: DiagnosisGap[],
  onToggle: (expanded: boolean, gap: DiagnosisGap) => void,
) {
  const {
    isVimOs,
    platformActions: { isAppOpen },
  } = useVimOsMigrationAPI();
  const { notify } = useSdkNotifications(isVimOs);

  const [initialized, setInitialized] = useState(false);
  const [autoResolveGapStatuses, setAutoResolveGapStatuses] =
    useState<Map<number, AutoResolveGapStatus>>();
  const gapCardRefs = useRef<Map<number, HTMLDivElement | null>>(new Map());

  useEffect(() => {
    if (!initialized) {
      const autoResolveStatusList = new Map<number, AutoResolveGapStatus>(
        gaps.map((gap) => [gap.position!, AutoResolveGapStatus.NOT_SCANNED]),
      );
      setAutoResolveGapStatuses(autoResolveStatusList);
      setInitialized(true);
    }
  }, [gaps, initialized]);

  const setAutoResolveStatus = useCallback((status: AutoResolveGapStatus, position?: number) => {
    setAutoResolveGapStatuses((prev) => prev?.set(position!, status));
  }, []);

  const getGapAutoResolvedStatus = useCallback(
    (position?: number) => autoResolveGapStatuses?.get(position!),
    [autoResolveGapStatuses],
  );

  const buildNotificationConfig = useCallback(
    ({
      autoResolvedGapsCount,
      autoResolvedGapsIcds,
    }: {
      autoResolvedGapsCount: number;
      autoResolvedGapsIcds: Set<string | undefined>;
    }): PushNotificationPayload => ({
      text: autoResolveNotification.getText(
        autoResolvedGapsCount,
        Array.from(autoResolvedGapsIcds),
      ),
      notificationId: uuidv4(),
      actionButtons: {
        rightButton: {
          text: autoResolveNotification.reviewInAppActionButton,
          buttonStyle: ButtonStyle.PRIMARY,
          openAppButton: true,
          callback: () => {
            diagnosisGapsLogger.info(
              'PI feature rollout - Review in app clicked from auto-resolved gaps notification',
            );
            const firstAutoResolvedGap = gaps.find(
              (gap) =>
                autoResolveGapStatuses?.get(gap.position!) ===
                AutoResolveGapStatus.NOTIFIED_AUTO_RESOLVED,
            );
            if (firstAutoResolvedGap && gapCardRefs.current.has(firstAutoResolvedGap.position!)) {
              diagnosisGapsLogger.info(
                'PI feature rollout - Scroll to and expand first auto-resolved gap at position',
                { firstAutoResolvedGap: firstAutoResolvedGap?.position },
              );
              onToggle(true, firstAutoResolvedGap!);
              gapCardRefs.current.get(firstAutoResolvedGap.position!)?.scrollIntoView({
                behavior: 'smooth',
              });
            }
          },
        },
        leftButton: {
          text: autoResolveNotification.closeActionButton,
          buttonStyle: ButtonStyle.LINK,
          openAppButton: false,
          callback: () => {
            diagnosisGapsLogger.info('PI feature rollout - Close auto-resolved gaps notification');
          },
        },
      },
    }),
    [autoResolveGapStatuses, gaps, onToggle],
  );

  const notifyAutoResolvedGapsIfNeeded = useCallback(() => {
    const autoResolvedGaps = gaps.filter(({ position }) => {
      const status = autoResolveGapStatuses?.get(position!);
      return (
        status === AutoResolveGapStatus.READY_TO_AUTO_RESOLVED ||
        status === AutoResolveGapStatus.AUTO_RESOLVED
      );
    });

    if (isEmpty(autoResolvedGaps)) {
      diagnosisGapsLogger.info('PI feature rollout - No auto-resolved gaps to notify', {
        autoResolveGapStatuses: autoResolveGapStatuses?.values(),
      });
      return;
    }

    const autoResolvedGapsIcds = new Set(
      autoResolvedGaps.flatMap((gap) =>
        gap.diagnoses.map((diagnose) => diagnose.id).filter((icd) => icd),
      ),
    );

    const notificationConfig = buildNotificationConfig({
      autoResolvedGapsCount: autoResolvedGaps.length,
      autoResolvedGapsIcds,
    });
    diagnosisGapsLogger.info(
      'PI feature rollout - initiating auto-resolved gaps push notification',
      {
        autoResolvedGapsIcds: [...autoResolvedGapsIcds],
        isAppOpen: !!isAppOpen,
      },
    );

    notify(notificationConfig);

    setAutoResolveGapStatuses((prev) => {
      const updatedAutoResolveGapStatuses = new Map<number, AutoResolveGapStatus>(prev);
      autoResolvedGaps.forEach(({ position }) =>
        updatedAutoResolveGapStatuses?.set(position!, AutoResolveGapStatus.NOTIFIED_AUTO_RESOLVED),
      );
      return updatedAutoResolveGapStatuses;
    });
  }, [gaps, autoResolveGapStatuses, notify, buildNotificationConfig]);

  useEffect(() => {
    const allGapsChecked =
      autoResolveGapStatuses &&
      gaps.every((gap) => {
        return autoResolveGapStatuses?.get(gap.position!) !== AutoResolveGapStatus.NOT_SCANNED;
      });

    if (allGapsChecked && isVimOs) {
      diagnosisGapsLogger.info(
        'PI feature rollout - Diagnosis gaps - Calling auto-resolved push notification',
        {
          autoResolveGapStatuses: autoResolveGapStatuses?.values(),
          isAppOpen: !!isAppOpen,
        },
      );
      notifyAutoResolvedGapsIfNeeded();
    }
  }, [autoResolveGapStatuses, notifyAutoResolvedGapsIfNeeded, gaps, isVimOs, isAppOpen]);

  return {
    getGapAutoResolvedStatus,
    setAutoResolveStatus,
    gapCardRefs,
  };
}
