import { LazyQueryHookOptions, useLazyQuery } from '@apollo/client';
import { useEffect, useState } from 'react';
import { diagnosisGapsLogger } from '../logic/logger';
import { DismissReason } from '../types';
import { GET_DISMISS_REASONS_QUERY } from '../api/queries/getDismissReasons';

type UseGetDismissReasons = [
  getDismissReasons: (options?: LazyQueryHookOptions) => void,
  dismissReasons: DismissReason[] | undefined,
  loaded: boolean,
];

export default function useGetDismissReasons(): UseGetDismissReasons {
  const [dismissReasons, setDismissReasons] = useState<DismissReason[]>();

  const [getDismissReasons, { error: getDismissReasonsError, loading: getDismissReasonsLoading }] =
    useLazyQuery(GET_DISMISS_REASONS_QUERY, {
      fetchPolicy: 'network-only',
      onCompleted: (data) => {
        if (
          data?.getDiagnosisGapsDismissReasons &&
          Array.isArray(data.getDiagnosisGapsDismissReasons) &&
          data.getDiagnosisGapsDismissReasons.length > 0
        ) {
          const dismissReasons = data.getDiagnosisGapsDismissReasons.map((reason) => ({
            reasonCode: reason.code,
            displayName: reason.name,
            isFreeTextRequired: reason.isFreeTextRequired,
          }));
          setDismissReasons(dismissReasons);
        }
      },
    });

  useEffect(() => {
    if (!getDismissReasonsLoading) {
      if (getDismissReasonsError) {
        diagnosisGapsLogger.error('Failed to fetch get dismiss reasons query', {
          error: getDismissReasonsError,
        });
      } else if (dismissReasons) {
        diagnosisGapsLogger.info('GetDismissReasons fetched successfully', {
          result: dismissReasons,
        });
      }
    }
  }, [getDismissReasonsError, dismissReasons, getDismissReasonsLoading]);

  return [getDismissReasons, dismissReasons, getDismissReasonsLoading];
}
