import { useVimOsMigrationAPI } from '@getvim-core-apps/vim-os-migration-api';
import { APP_SIZE_MAP } from '@getvim-core-apps/vim-os-migration-api/types';
import { AtomicDialog, Toast, useDialogState } from '@getvim/atomic-ui';
import { isEmpty } from 'lodash-es';
import React, { FC, useCallback, useContext, useEffect, useState } from 'react';

import { GlobalContext } from '../../contexts/globalContext';
import { DocumentViewerCloseReason } from '../../logic/analytics';
import { diagnosisGapsLogger } from '../../logic/logger';
import { DiagnosisGap, DocumentData, DocumentMetadata } from '../../types';
import { ActionButton } from '../ActionButton/ActionButton';
import './DocumentViewer.less';
import { DocumentViewerLoader } from './DocumentViewerLoader';
import { widgetId } from '../../consts';
import { analyticsManager } from '../../utils/analyticManager';

export const DocumentViewer: FC<{
  gap: DiagnosisGap;
  documentData: DocumentData;
  closeDocumentViewerComponent(closeReason: DocumentViewerCloseReason): void;
}> = ({ gap, documentData, closeDocumentViewerComponent }) => {
  const {
    config: { organization, user },
  } = useVimOsMigrationAPI();

  const { documentViewerServerUrl } = useContext(GlobalContext);

  const [documentReady, setDocumentReady] = useState<boolean>(false);
  const [viewerLoaded, setViewerLoaded] = useState<boolean>(false);
  const [viewerError, setViewerError] = useState<boolean>(false);
  const [startTime] = useState<number>(performance.now());
  const dialog = useDialogState();
  const { createToast, ToastTypes } = Toast;

  const [documentBuffer, setDocumentBuffer] = useState<ArrayBuffer>();
  const [documentMetadata, setDocumentMetadata] = useState<DocumentMetadata>();

  const handleLoadingError = useCallback(
    (error) => {
      diagnosisGapsLogger.warning('An error occoured when trying to load file', {
        gapId: gap.gapId,
        documentUrl: gap.contentSupplierSpecificFields?.documentUrl,
        error,
      });
      setViewerError(true);
    },
    [gap],
  );

  useEffect(() => {
    if (documentData) {
      if (documentData.fetchFailed) {
        /*
        If pre fetch of the document failed, the button should be disabled.
        However, if the user clicked the button before the pre-fetch failed, we need to handle the error here
        */
        handleLoadingError('Failed to fetch document url');
      } else {
        setDocumentBuffer(documentData.buffer?.slice(0));
        setDocumentMetadata({
          highlights: documentData.highlights,
          documentExtension: documentData.documentExtension,
          userData: {
            organizationName: organization.name,
            userEmail: user.email,
          },
        });
      }
    }
  }, [documentData, handleLoadingError, organization.name, user.email]);

  const closeViewer = useCallback(
    (closeReason: DocumentViewerCloseReason) => {
      setDocumentReady(false);
      closeDocumentViewerComponent(closeReason);
      dialog.setVisible(false);
    },
    [dialog, closeDocumentViewerComponent],
  );

  useEffect(() => {
    if (viewerError) {
      closeViewer(DocumentViewerCloseReason.ERROR);
    }
  }, [viewerError, closeViewer]);

  useEffect(() => {
    const listener = (message) => {
      if (message.origin !== documentViewerServerUrl) {
        return;
      }

      if (message.data?.viewerLoaded) {
        setViewerLoaded(true);
      } else if (message.data?.viewerReady) {
        const bytesToMegaBytes = (bytes = 0) => (bytes / (1024 * 1024)).toFixed(2);

        const { documentExtension: bufferExtension, requestHeaders } = documentData ?? {};
        const dataSize = bytesToMegaBytes(requestHeaders?.['content-length']);

        const { tiffLogic } = message.data;
        analyticsManager.track('dx_document_loaded', {
          gap_code: gap.hcc.code,
          contain_highlights: !isEmpty(documentMetadata?.highlights),
          loading_time: (performance.now() - startTime).toFixed(3),
          document_extension: bufferExtension,
          tiff_logic: tiffLogic,
          file_size_mb: dataSize,
          file_content_type: requestHeaders?.['content-type'],
          app_name: widgetId,
        });
        setDocumentReady(true);
      } else if (message.data?.closeViewer) {
        closeViewer(DocumentViewerCloseReason.CLOSE);
      } else if (message.data?.viewerError) {
        handleLoadingError(message.data?.error);
      }
    };
    dialog.setVisible(true);

    window.addEventListener('message', listener);
    return () => {
      window.removeEventListener('message', listener);
      if (viewerError) {
        createToast({
          title: 'Error!',
          message: 'An error occurred while trying to load the file',
          type: ToastTypes.ERROR,
        });
      }
    };
  });

  useEffect(() => {
    if (!viewerLoaded || !documentBuffer) return;

    const documentViewerIframe: HTMLIFrameElement = document.getElementById(
      'document-viewer',
    ) as HTMLIFrameElement;

    if (
      !documentViewerIframe ||
      !documentViewerServerUrl ||
      !documentBuffer ||
      documentBuffer?.byteLength === 0
    )
      return;

    documentViewerIframe.contentWindow?.postMessage(
      { dataReady: true, ...documentMetadata, buffer: documentBuffer },
      documentViewerServerUrl,
      [documentBuffer],
    );
  }, [documentViewerServerUrl, viewerLoaded, documentBuffer, documentMetadata]);

  return (
    <AtomicDialog className="document-viewer-dialog" dialog={dialog}>
      <>
        {!documentReady && (
          <div className="document-viewer-loading">
            <DocumentViewerLoader />
            <div className="document-viewer-cancel-loading ">
              <ActionButton onClick={() => closeViewer(DocumentViewerCloseReason.CANCEL)}>
                Cancel
              </ActionButton>
            </div>
          </div>
        )}
        {documentViewerServerUrl && (
          <div className="diagnosis-gaps_document-viewer-window">
            <iframe
              key={gap.gapId}
              id="document-viewer"
              src={documentViewerServerUrl}
              width={APP_SIZE_MAP.LARGE.width}
            />
          </div>
        )}
      </>
    </AtomicDialog>
  );
};
