import { UndoButtonState } from '@getvim/react-app-infra';
import { createContext } from 'react';
import { cdeTriggerSupportedSources, documentViewerSupportedSources } from '../consts';
import { TriggerType } from '../types';

export const UNDO_ACTION_TIME_DEFAULT = 3_600_000;

export type GlobalContextObj = {
  shouldSelectDataIcds: boolean;
  shouldAutoResolvedGap: boolean;
  undoConfig: { [key: string]: UndoButtonState };
  documentViewerServerUrl?: string;
  documentViewerSupportedSources: string[];
  shouldSupportUndoMultisession: boolean;
  undoActionTime: number;
  shouldShowHccModel: boolean;
  shouldAddAlreadyCodedOnNonSuggestedIcds: boolean;
  cdeTriggerSupportedSources: { [key: string]: TriggerType[] };
  cdeTriggerCache: Set<string>;
  setCdeTriggerCache: React.Dispatch<React.SetStateAction<Set<string>>>;
  shouldUseDynamicOriginForDocumentViewer: boolean;
  shouldDisableCalendarView: boolean;
  shouldAgreeWithoutWriteback: boolean;
  shouldUseSourceVaultTokens: boolean;
};

export const GlobalContext = createContext<GlobalContextObj>({
  shouldSelectDataIcds: false,
  shouldAutoResolvedGap: false,
  undoConfig: {},
  documentViewerServerUrl: undefined,
  documentViewerSupportedSources,
  shouldSupportUndoMultisession: false,
  undoActionTime: UNDO_ACTION_TIME_DEFAULT,
  shouldShowHccModel: false,
  shouldAddAlreadyCodedOnNonSuggestedIcds: false,
  cdeTriggerSupportedSources,
  cdeTriggerCache: new Set<string>(),
  setCdeTriggerCache: () => {},
  shouldUseDynamicOriginForDocumentViewer: false,
  shouldDisableCalendarView: false,
  shouldAgreeWithoutWriteback: false,
  shouldUseSourceVaultTokens: false,
});
